-- Practical FRAME project, four cumulative checks, and an aggregate final exam.
-- Guard the exam endpoint before publishing blocks so the generic acknowledgement cannot bypass it.
SET lock_timeout = '5s';

ALTER TABLE public.academy_lesson_blocks
  DROP CONSTRAINT academy_lesson_blocks_block_type_check;
ALTER TABLE public.academy_lesson_blocks
  ADD CONSTRAINT academy_lesson_blocks_block_type_check CHECK (block_type IN (
    'objective','hook','concept','rich_text','step_reveal','before_after','flip_cards',
    'sequence_sort','matching','image_hotspot','decision_tree','case_study','scenario',
    'client_simulation','calculator','prompt_builder','practical_response','reflection',
    'checklist','quiz','course_exam','homework','submission','example','summary'
  ));

CREATE OR REPLACE FUNCTION academy_private.complete_lesson_block(p_module text, p_lesson text, p_version uuid, p_block_key text, p_payload jsonb, p_attempt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=(SELECT auth.uid()); l public.academy_lessons; b public.academy_lesson_blocks; k academy_private.lesson_block_keys; prev public.academy_lesson_attempts_v2; complete boolean:=false; correct boolean:=NULL; score_value integer:=0; max_value integer:=0; response jsonb:='{}'; expected jsonb; supplied jsonb; required_ids text[]; progress jsonb; admin_preview boolean:=false;
BEGIN
 IF NOT academy_private.can_access(p_module) OR (uid IS NULL AND p_module<>'s01-m01') THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR pg_column_size(p_payload)>65536 THEN RAISE EXCEPTION 'Invalid interaction payload'; END IF;
 SELECT * INTO l FROM public.academy_lessons WHERE module_id=p_module AND lesson_id=p_lesson;
 IF NOT FOUND THEN RAISE EXCEPTION 'Lesson not found'; END IF;
 admin_preview:=uid IS NOT NULL AND academy_private.is_admin() AND p_version IS DISTINCT FROM l.published_version_id
  AND EXISTS(SELECT 1 FROM public.academy_lesson_versions WHERE id=p_version AND academy_lesson_id=l.id);
 IF NOT admin_preview AND (l.status='archived' OR l.published_version_id IS DISTINCT FROM p_version) THEN RAISE EXCEPTION 'Lesson version changed'; END IF;
 SELECT * INTO b FROM public.academy_lesson_blocks WHERE version_id=p_version AND block_key=p_block_key;
 IF b.id IS NULL THEN RAISE EXCEPTION 'Block not found'; END IF;
 IF b.block_type='course_exam' THEN RAISE EXCEPTION 'Use the course exam endpoint'; END IF;
 IF uid IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_attempt::text,0));
  SELECT * INTO prev FROM public.academy_lesson_attempts_v2 WHERE id=p_attempt;
  IF FOUND THEN
   IF prev.user_id<>uid OR prev.block_id<>b.id OR prev.payload<>p_payload THEN RAISE EXCEPTION 'Attempt conflict'; END IF;
   RETURN jsonb_build_object('attemptId',prev.id,'correct',prev.is_correct,'score',prev.score,'maxScore',prev.max_score,'feedback',prev.feedback,'progress',(SELECT to_jsonb(p) FROM public.academy_lesson_progress p WHERE p.user_id=uid AND p.academy_lesson_id=l.id));
  END IF;
 END IF;
 SELECT * INTO k FROM academy_private.lesson_block_keys WHERE block_id=b.id;
 expected:=coalesce(k.answer_key,'{}');
 CASE b.block_type
  WHEN 'sequence_sort' THEN supplied:=p_payload->'order'; correct:=supplied=expected->'order'; complete:=correct;
  WHEN 'matching' THEN supplied:=p_payload->'matches'; correct:=supplied=expected->'matches'; complete:=correct;
  WHEN 'image_hotspot' THEN correct:=p_payload->>'selected'=expected->>'correct'; complete:=correct;
  WHEN 'quiz' THEN correct:=p_payload->'answer'=expected->'correct'; complete:=correct;
  WHEN 'calculator' THEN
   IF coalesce(p_payload->>'value','')!~'^[-+]?[0-9]+([.][0-9]+)?$' THEN RAISE EXCEPTION 'Invalid calculator value'; END IF;
   correct:=(p_payload->>'value')::numeric BETWEEN coalesce((expected->>'min')::numeric,(expected->>'value')::numeric) AND coalesce((expected->>'max')::numeric,(expected->>'value')::numeric); complete:=correct;
  WHEN 'decision_tree' THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b.content->'options','[]'::jsonb)) o WHERE o->>'id'=p_payload->>'selected') THEN RAISE EXCEPTION 'Invalid choice'; END IF;
   correct:=CASE WHEN expected ? 'correct' THEN p_payload->>'selected'=expected->>'correct' ELSE NULL END; complete:=true;
  WHEN 'scenario' THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b.content->'options','[]'::jsonb)) o WHERE o->>'id'=p_payload->>'selected') THEN RAISE EXCEPTION 'Invalid choice'; END IF;
   correct:=CASE WHEN expected ? 'correct' THEN p_payload->>'selected'=expected->>'correct' ELSE NULL END; complete:=coalesce(correct,true);
  WHEN 'client_simulation' THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b.content->'options','[]'::jsonb)) o WHERE o->>'id'=p_payload->>'selected') THEN RAISE EXCEPTION 'Invalid choice'; END IF;
   correct:=CASE WHEN expected ? 'correct' THEN p_payload->>'selected'=expected->>'correct' ELSE NULL END; complete:=true;
  WHEN 'flip_cards' THEN
   SELECT array_agg(value->>'id' ORDER BY value->>'id') INTO required_ids FROM jsonb_array_elements(coalesce(b.content->'cards','[]'));
   complete:=coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'viewed','[]')) ORDER BY 1),'{}') @> coalesce(required_ids,'{}');
  WHEN 'step_reveal' THEN
   SELECT array_agg(value->>'id' ORDER BY value->>'id') INTO required_ids FROM jsonb_array_elements(coalesce(b.content->'steps','[]'));
   complete:=coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'revealed','[]')) ORDER BY 1),'{}') @> coalesce(required_ids,'{}');
  WHEN 'checklist' THEN
   SELECT array_agg(value->>'id' ORDER BY value->>'id') INTO required_ids FROM jsonb_array_elements(coalesce(b.content->'items','[]')) WHERE coalesce((value->>'required')::boolean,true);
   complete:=coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'checked','[]')) ORDER BY 1),'{}') @> coalesce(required_ids,'{}');
  WHEN 'prompt_builder' THEN complete:=jsonb_typeof(p_payload->'fields')='object' AND (SELECT count(*) FROM jsonb_each_text(p_payload->'fields') WHERE length(btrim(value))>=2)>=coalesce((b.content->>'minFields')::integer,2);
  WHEN 'practical_response' THEN complete:=length(btrim(coalesce(p_payload->>'text','')))>=coalesce((b.content->>'minLength')::integer,20);
  WHEN 'reflection' THEN complete:=length(btrim(coalesce(p_payload->>'text','')))>=coalesce((b.content->>'minLength')::integer,20);
  WHEN 'homework' THEN complete:=length(btrim(coalesce(p_payload->>'text','')))>=coalesce((b.content->>'minLength')::integer,20);
  WHEN 'submission' THEN complete:=(p_payload->>'kind' IN ('link','file')) AND length(btrim(coalesce(p_payload->>'value','')))>=5 AND (p_payload->>'kind'<>'file' OR p_payload->>'value' LIKE uid::text||'/%');
  ELSE complete:=coalesce((p_payload->>'acknowledged')::boolean,false);
 END CASE;
 max_value:=CASE WHEN correct IS NULL THEN 0 ELSE b.points END;
 score_value:=CASE WHEN correct THEN b.points ELSE 0 END;
 response:=coalesce(k.feedback,'{}')||jsonb_build_object('complete',complete);
 IF correct IS NOT NULL THEN
  response:=response||jsonb_build_object('correct',correct);
  IF NOT (p_module IN ('s02-m01','s02-m02','s02-m03') AND correct IS DISTINCT FROM TRUE) THEN
   response:=response||jsonb_build_object('answer',expected);
  END IF;
 END IF;
 IF uid IS NULL OR admin_preview THEN
  RETURN jsonb_build_object('attemptId',p_attempt,'correct',correct,'score',score_value,'maxScore',max_value,'feedback',response,'progress',NULL,'preview',true);
 END IF;
 INSERT INTO public.academy_lesson_attempts_v2(id,user_id,academy_lesson_id,version_id,block_id,payload,score,max_score,is_correct,feedback)
 VALUES(p_attempt,uid,l.id,p_version,b.id,p_payload,score_value,max_value,correct,response);
 INSERT INTO public.academy_lesson_progress(user_id,academy_lesson_id,version_id,current_block_key,block_state,completed_block_keys)
 VALUES(uid,l.id,p_version,p_block_key,jsonb_build_object(p_block_key,p_payload),CASE WHEN complete THEN ARRAY[p_block_key] ELSE '{}' END)
 ON CONFLICT(user_id,academy_lesson_id) DO UPDATE SET version_id=EXCLUDED.version_id,current_block_key=EXCLUDED.current_block_key,
  block_state=CASE WHEN academy_lesson_progress.version_id=EXCLUDED.version_id THEN academy_lesson_progress.block_state||EXCLUDED.block_state ELSE EXCLUDED.block_state END,
  completed_block_keys=CASE
   WHEN academy_lesson_progress.version_id<>EXCLUDED.version_id THEN EXCLUDED.completed_block_keys
   WHEN complete AND NOT p_block_key=ANY(academy_lesson_progress.completed_block_keys) THEN array_append(academy_lesson_progress.completed_block_keys,p_block_key)
   ELSE academy_lesson_progress.completed_block_keys END,
  xp=CASE WHEN academy_lesson_progress.version_id=EXCLUDED.version_id THEN academy_lesson_progress.xp ELSE 0 END,
  score_percent=CASE WHEN academy_lesson_progress.version_id=EXCLUDED.version_id THEN academy_lesson_progress.score_percent ELSE NULL END,
  mastery_status=CASE WHEN academy_lesson_progress.version_id=EXCLUDED.version_id THEN academy_lesson_progress.mastery_status ELSE 'learning' END,
  completed_at=CASE WHEN academy_lesson_progress.version_id=EXCLUDED.version_id THEN academy_lesson_progress.completed_at ELSE NULL END,
  last_activity_at=now();
 progress:=academy_private.refresh_lesson_progress(uid,l.id);
 RETURN jsonb_build_object('attemptId',p_attempt,'correct',correct,'score',score_value,'maxScore',max_value,'feedback',response,'progress',progress);
END $function$;

CREATE OR REPLACE FUNCTION academy_private.lesson_validation(p_version uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v public.academy_lesson_versions;
  errors jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;
  n integer;
  kinds text[];
BEGIN
  SELECT * INTO v FROM public.academy_lesson_versions WHERE id=p_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF;

  SELECT count(*),coalesce(array_agg(DISTINCT block_type),'{}')
    INTO n,kinds
  FROM public.academy_lesson_blocks WHERE version_id=p_version;

  IF btrim(v.objective)='' THEN errors:=errors||jsonb_build_array('missing_objective'); END IF;
  IF btrim(v.hook)='' THEN errors:=errors||jsonb_build_array('missing_hook'); END IF;
  IF n<5 THEN errors:=errors||jsonb_build_array('too_few_blocks'); END IF;
  IF NOT (kinds && ARRAY[
    'sequence_sort','matching','image_hotspot','decision_tree','scenario',
    'client_simulation','calculator','prompt_builder','practical_response',
    'reflection','checklist','quiz','course_exam','homework','submission','flip_cards'
  ]) THEN errors:=errors||jsonb_build_array('missing_interaction'); END IF;
  IF NOT (kinds && ARRAY['quiz','course_exam']) THEN errors:=errors||jsonb_build_array('missing_knowledge_check'); END IF;
  IF NOT (
    kinds && ARRAY['prompt_builder','practical_response','homework','submission']
    OR (
      EXISTS (
        SELECT 1 FROM public.academy_lessons l
        WHERE l.id=v.academy_lesson_id
          AND l.module_id IN (
            's02-m01','s02-m02','s02-m03','s02-m04','s02-m05','s02-m06',
            's02-m07','s02-m08','s02-m09',
            's02-m10','s02-m11','s02-m12',
            's02-m13','s02-m14','s02-m15'
          )
      )
      AND kinds && ARRAY[
        'sequence_sort','matching','image_hotspot','decision_tree',
        'scenario','client_simulation','calculator','course_exam'
      ]
    )
  ) THEN errors:=errors||jsonb_build_array('missing_practice'); END IF;
  IF NOT ('summary'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_summary'); END IF;
  IF EXISTS (
    SELECT 1 FROM public.academy_lesson_blocks b
    WHERE b.version_id=p_version AND b.required AND b.points=0
  ) THEN warnings:=warnings||jsonb_build_array('required_block_has_no_xp'); END IF;
  IF EXISTS (
    SELECT 1
    FROM public.academy_lesson_blocks b
    LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id
    WHERE b.version_id=p_version
      AND b.block_type IN (
        'sequence_sort','matching','image_hotspot','decision_tree','scenario',
        'client_simulation','calculator','quiz','course_exam'
      )
      AND k.block_id IS NULL
  ) THEN errors:=errors||jsonb_build_array('missing_server_evaluation'); END IF;

  RETURN jsonb_build_object(
    'errors',errors,
    'warnings',warnings,
    'block_count',n,
    'interactive',kinds && ARRAY[
      'sequence_sort','matching','image_hotspot','decision_tree','scenario',
      'client_simulation','calculator','prompt_builder','practical_response',
      'reflection','checklist','quiz','course_exam','homework','submission','flip_cards'
    ],
    'has_quiz',kinds && ARRAY['quiz','course_exam'],
    'has_assignment',kinds && ARRAY['practical_response','homework','submission']
  );
END
$function$;





CREATE FUNCTION academy_private.submit_course_exam(
  p_module text,p_lesson text,p_version uuid,p_block_key text,p_payload jsonb,p_attempt uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $exam$
DECLARE
  uid uuid := (SELECT auth.uid());
  lesson_row public.academy_lessons;
  exam_block public.academy_lesson_blocks;
  previous public.academy_lesson_attempts_v2;
  question jsonb;
  answers jsonb;
  expected jsonb;
  provided text;
  total integer;
  passed_count integer := 0;
  exam_percent integer;
  score_value integer;
  weak_modules text[] := ARRAY[]::text[];
  prior_count integer;
  result jsonb;
  progress jsonb;
BEGIN
  IF uid IS NULL OR p_module <> 's02-m15' OR NOT academy_private.can_access(p_module) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE='42501';
  END IF;
  IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR
     pg_column_size(p_payload)>65536 OR jsonb_typeof(p_payload->'answers') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Invalid exam payload';
  END IF;
  SELECT * INTO lesson_row FROM public.academy_lessons
  WHERE module_id=p_module AND lesson_id=p_lesson AND status='published'
    AND published_version_id=p_version;
  IF NOT FOUND OR p_lesson NOT IN ('pv15-09','pv15-10','pv15-11','pv15-12','pv15-13') THEN
    RAISE EXCEPTION 'Published exam not found';
  END IF;
  SELECT * INTO exam_block FROM public.academy_lesson_blocks
  WHERE version_id=p_version AND block_key=p_block_key AND block_type='course_exam';
  IF NOT FOUND THEN RAISE EXCEPTION 'Exam block not found'; END IF;
  SELECT k.answer_key->'answers' INTO expected
  FROM academy_private.lesson_block_keys k WHERE k.block_id=exam_block.id;
  IF jsonb_typeof(expected) IS DISTINCT FROM 'object' OR
     jsonb_typeof(exam_block.content->'questions') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Exam has no answer key';
  END IF;

  -- Serialize concurrent attempts for the same learner and block.
  PERFORM pg_advisory_xact_lock(hashtextextended(uid::text || ':' || exam_block.id::text,0));
  SELECT * INTO previous FROM public.academy_lesson_attempts_v2 WHERE id=p_attempt;
  IF FOUND THEN
    IF previous.user_id<>uid OR previous.block_id<>exam_block.id OR previous.payload<>p_payload THEN
      RAISE EXCEPTION 'Attempt conflict';
    END IF;
    RETURN jsonb_build_object('attemptId',previous.id,'correct',previous.is_correct,
      'score',previous.score,'maxScore',previous.max_score,'feedback',previous.feedback,
      'progress',(SELECT to_jsonb(p) FROM public.academy_lesson_progress p
        WHERE p.user_id=uid AND p.academy_lesson_id=lesson_row.id));
  END IF;
  IF EXISTS (SELECT 1 FROM public.academy_lesson_progress p
    WHERE p.user_id=uid AND p.academy_lesson_id=lesson_row.id AND p.version_id=p_version
      AND p_block_key=ANY(p.completed_block_keys)) THEN
    RAISE EXCEPTION 'Exam already passed';
  END IF;
  IF p_lesson='pv15-13' THEN
    SELECT count(*) INTO prior_count FROM public.academy_lessons l
    JOIN public.academy_lesson_progress p ON p.academy_lesson_id=l.id
      AND p.user_id=uid AND p.version_id=l.published_version_id AND p.completed_at IS NOT NULL
    WHERE l.module_id='s02-m15' AND l.lesson_id BETWEEN 'pv15-01' AND 'pv15-12';
    IF prior_count<>12 THEN
      RAISE EXCEPTION 'Complete the 12 previous module 15 lessons before the final exam';
    END IF;
  END IF;

  answers:=p_payload->'answers';
  total:=jsonb_array_length(exam_block.content->'questions');
  IF total NOT BETWEEN 8 AND 35 OR
     (SELECT count(*) FROM jsonb_object_keys(answers))<>total OR
     (SELECT count(*) FROM jsonb_object_keys(expected))<>total THEN
    RAISE EXCEPTION 'Answer every exam question exactly once';
  END IF;
  FOR question IN SELECT value FROM jsonb_array_elements(exam_block.content->'questions') LOOP
    provided:=answers->>(question->>'id');
    IF provided IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(question->'options') o
      WHERE o->>'id'=provided
    ) THEN
      RAISE EXCEPTION 'Invalid or missing exam choice';
    END IF;
    IF provided=expected->>(question->>'id') THEN
      passed_count:=passed_count+1;
    ELSIF NOT (question->>'moduleId')=ANY(weak_modules) THEN
      weak_modules:=array_append(weak_modules,question->>'moduleId');
    END IF;
  END LOOP;
  exam_percent:=round(100.0*passed_count/total)::integer;
  score_value:=round(exam_block.points::numeric*passed_count/total)::integer;
  result:=jsonb_build_object('complete',exam_percent>=80,
    'scorePercent',exam_percent,'correctCount',passed_count,'totalQuestions',total,
    'weakModules',to_jsonb(weak_modules),
    'explanation',CASE WHEN exam_percent>=80 THEN
      'Изпитът е преминат. Виж темите с грешки и провери тези решения в собствения си проект.'
      ELSE 'Повтори темите с грешки, после предай нов пълен опит. Верните отговори не се показват.' END);
  INSERT INTO public.academy_lesson_attempts_v2(
    id,user_id,academy_lesson_id,version_id,block_id,payload,score,max_score,is_correct,feedback)
  VALUES(p_attempt,uid,lesson_row.id,p_version,exam_block.id,p_payload,
    score_value,exam_block.points,exam_percent>=80,result);
  INSERT INTO public.academy_lesson_progress(
    user_id,academy_lesson_id,version_id,current_block_key,block_state,completed_block_keys)
  VALUES(uid,lesson_row.id,p_version,p_block_key,jsonb_build_object(p_block_key,p_payload),
    CASE WHEN exam_percent>=80 THEN ARRAY[p_block_key] ELSE ARRAY[]::text[] END)
  ON CONFLICT(user_id,academy_lesson_id) DO UPDATE SET
    version_id=EXCLUDED.version_id,current_block_key=EXCLUDED.current_block_key,
    block_state=CASE WHEN academy_lesson_progress.version_id=EXCLUDED.version_id
      THEN academy_lesson_progress.block_state||EXCLUDED.block_state ELSE EXCLUDED.block_state END,
    completed_block_keys=CASE WHEN academy_lesson_progress.version_id<>EXCLUDED.version_id
      THEN EXCLUDED.completed_block_keys
      WHEN exam_percent>=80 AND NOT p_block_key=ANY(academy_lesson_progress.completed_block_keys)
      THEN array_append(academy_lesson_progress.completed_block_keys,p_block_key)
      ELSE academy_lesson_progress.completed_block_keys END,
    last_activity_at=now();
  progress:=academy_private.refresh_lesson_progress(uid,lesson_row.id);
  RETURN jsonb_build_object('attemptId',p_attempt,'correct',exam_percent>=80,
    'score',score_value,'maxScore',exam_block.points,'feedback',result,'progress',progress);
END $exam$;

CREATE FUNCTION public.academy_submit_course_exam(
  p_module text,p_lesson text,p_version uuid,p_block_key text,p_payload jsonb,p_attempt uuid)
RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $wrapper$
  SELECT academy_private.submit_course_exam(p_module,p_lesson,p_version,p_block_key,p_payload,p_attempt)
$wrapper$;
REVOKE ALL ON FUNCTION academy_private.submit_course_exam(text,text,uuid,text,jsonb,uuid) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.academy_submit_course_exam(text,text,uuid,text,jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION academy_private.submit_course_exam(text,text,uuid,text,jsonb,uuid),
  public.academy_submit_course_exam(text,text,uuid,text,jsonb,uuid) TO authenticated;

DO $release$
DECLARE
  payload jsonb := $curriculum$[{"module_id":"s02-m15","lesson_id":"pv15-01","title":"Избери изпълним бриф и граници на проекта","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка.","hook":"Малка пекарна иска „видео, което да стане вирусно“. Няма бюджет за актьори, собственикът може да отдели два часа и не иска да показва клиенти.","estimated_minutes":35,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Малка пекарна иска „видео, което да стане вирусно“. Няма бюджет за актьори, собственикът може да отдели два часа и не иска да показва клиенти."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"Свали обещанието на земята. Клиентът не може да поръча гледания, но може да постави проверима задача: правилните хора да разберат какво се пече, кога и как да поръчат. Работи със собствен бизнес, позволен клиент или предоставения учебен бриф. За учебния бриф доказателството е изпълним план и собствен заснет материал; не се преструвай на реален клиентски резултат."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши кой взема решението, коя аудитория ще види видеото и каква стъпка трябва да направи тя.\n2. Отдели известните факти от допусканията и отвори списък с въпроси, които спират снимките.\n3. Провери хора, локация, продукти, музика, лого и разрешения за публикуване.\n4. Ограничи доставка: един основен клип, платформа, версии, срок и начин на проверка."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"Учебен бриф: 45–75 секунди за сутрешен хляб. Аудиторията са хора наблизо, които поръчват сутрин. Може да се снима собственикът и процесът в пекарната; клиентите не влизат в кадър. Действието е обаждане по показан номер, но номерът се потвърждава преди финалния експорт. Това са примерни условия, не данни от действащ бизнес."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Брифът казва само „динамично видео за всички платформи“ и обещава ръст на продажбите без базови данни."},"after":{"label":"Поправка","text":"Потвърди аудитория, продукт, едно действие и ограничения. Напиши какво ще измериш и какво няма как да докажеш с този проект."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Потвърди аудитория, продукт, едно действие и ограничения. Напиши какво ще измериш и какво няма как да докажеш с този проект.\n\nСтатусът остава проба, докато не покриеш критерия: Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Избери собствена тема или учебния пример. Направи бриф от една страница: цел, аудитория, обещание, доказателство, действие, платформа, позволени кадри, срок, отговорник и неизвестни. Запази версията преди поправките."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Ако работиш по учебния бриф, отбележи го навсякъде като симулация. Не използвай чуждо лого или чужд обект без разрешение."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"Your Europe, Copyright in the EU: https://europa.eu/youreurope/business/growing/protecting-intellectual-property/copyright/index_en.htm\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Клиентът иска „вирусно“. Коя цел можеш да приемеш?","options":[{"id":"a","label":"Ясно послание и проверимо действие за определена аудитория."},{"id":"b","label":"Гарантирани 100 000 гледания."},{"id":"c","label":"Едно видео за всички хора и всички платформи."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Ясно послание и проверимо действие за определена аудитория.\nКритерият за проверка: Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Нямаш разрешение да показваш клиентите в пекарната. Кой е работещият план?","options":[{"id":"a","label":"Снимаш клиентите и решаваш после."},{"id":"b","label":"Размазваш лица след публикация, без да сменяш плана."},{"id":"c","label":"Снимаш продукта и позволените хора; избягваш разпознаваеми клиенти."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Снимаш продукта и позволените хора; избягваш разпознаваеми клиенти.\nКритерият за проверка: Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кой признак показва, че брифът е годен за снимане?","options":[{"id":"a","label":"Избран е скъп обектив."},{"id":"b","label":"Има цел, аудитория, доставка, права, собственик и списък с неизвестни."},{"id":"c","label":"Има много прилагателни за стила."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Има цел, аудитория, доставка, права, собственик и списък с неизвестни.\nКритерият за проверка: Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Брифът казва само „динамично видео за всички платформи“ и обещава ръст на продажбите без базови данни. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Потвърди аудитория, продукт, едно действие и ограничения. Напиши какво ще измериш и какво няма как да докажеш с този проект."},{"id":"b","label":"Приемаш файла за готов без проверка."},{"id":"c","label":"Заменяш липсващото доказателство с общо обещание."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Потвърди аудитория, продукт, едно действие и ограничения. Напиши какво ще измериш и какво няма как да докажеш с този проект.\nКритерият за проверка: Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s3","text":"Провери хора, локация, продукти, музика, лого и разрешения за публикуване."},{"id":"s4","text":"Ограничи доставка: един основен клип, платформа, версии, срок и начин на проверка."},{"id":"s1","text":"Запиши кой взема решението, коя аудитория ще види видеото и каква стъпка трябва да направи тя."},{"id":"s2","text":"Отдели известните факти от допусканията и отвори списък с въпроси, които спират снимките."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Запиши кой взема решението, коя аудитория ще види видеото и каква стъпка трябва да направи тя. → Отдели известните факти от допусканията и отвори списък с въпроси, които спират снимките. → Провери хора, локация, продукти, музика, лого и разрешения за публикуване. → Ограничи доставка: един основен клип, платформа, версии, срок и начин на проверка."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["Свали обещанието на земята. Клиентът не може да поръча гледания, но може да постави проверима задача: правилните хора да разберат какво се пече, кога и как да поръчат. Работи със собствен бизнес, позволен клиент или предоставения учебен бриф. За учебния бриф доказателството е изпълним план и собствен заснет материал; не се преструвай на реален клиентски резултат.","Потвърди аудитория, продукт, едно действие и ограничения. Напиши какво ще измериш и какво няма как да докажеш с този проект.","Външен човек може да каже какво точно ще заснемеш, за кого, кой одобрява фактите и кое твърдение още чака проверка."],"nextStep":"Избери собствена тема или учебния пример. Направи бриф от една страница: цел, аудитория, обещание, доказателство, действие, платформа, позволени кадри, срок, отговорник и неизвестни. Запази версията преди поправките."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-02","title":"Focus: превърни целта в сценарий и списък с кадри","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора.","hook":"Снимаш хляб, но първите 20 секунди са красиво лого. Зрителят още не знае какво получава и кога.","estimated_minutes":45,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Снимаш хляб, но първите 20 секунди са красиво лого. Зрителят още не знае какво получава и кога."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"От брифа изведи едно обещание, което може да се види или чуе. Първият кадър трябва да даде причина точният човек да остане; после покажи доказателство и реална следваща стъпка. Списъкът с кадри съществува, за да не липсва материал за смислен монтаж: номер на кадър, действие, размер, звук, място и резервен вариант."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Преведи целта в един проблем на зрителя и едно конкретно обещание.\n2. Напиши хук, доказателствена сцена и действие; извади непотвърдените твърдения.\n3. Направи снимков план: широк, среден, детайл, говор/звук и преход за всяка важна сцена.\n4. Провери логистика, пауза за шум, реквизит и резервен кадър преди снимачния ден."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"За пекарната: първи кадър — разрязване на топъл хляб със собствен звук; втори — месене и фурна; трети — собственикът показва кога излиза партидата; край — потвърден начин за поръчка. Ако сутрешната фурна е шумна, краткото изречение се записва на тихо място. Кадърът не обещава постоянна наличност, ако тя не е потвърдена."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Сценарият е списък с ефекти, без план за най-важния кадър и без проверено действие."},"after":{"label":"Поправка","text":"Подреди причината за гледане, доказателството и действието. За всяко намерение запиши конкретен кадър и необходим звук."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Подреди причината за гледане, доказателството и действието. За всяко намерение запиши конкретен кадър и необходим звук.\n\nСтатусът остава проба, докато не покриеш критерия: При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Създай 45–75 секундно разкадровъчно решение или еквивалент за твоя формат. Предай една страница сценарий и таблица за 6–10 ключови кадъра с резервни кадри и източник на звук."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Не е нужен сториборд с рисунки, ако таблица с кадър, действие и звук води същата работа. Не снимай резервни кадри без връзка с монтажа."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"Adobe, How to make a shot list: https://www.adobe.com/uk/creativecloud/video/discover/shot-list.html\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кога снимковият план помага най-много?","options":[{"id":"a","label":"Когато изброява само обективите."},{"id":"b","label":"Когато замества проверката на брифа."},{"id":"c","label":"Когато свързва всяко обещание с нужен кадър, звук и резерв."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Когато свързва всяко обещание с нужен кадър, звук и резерв.\nКритерият за проверка: При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Липсва доказателствен кадър за „печем днес“. Какво правиш?","options":[{"id":"a","label":"Добавяш по-силна музика."},{"id":"b","label":"Променяш твърдението или добавяш позволен и възможен кадър от процеса."},{"id":"c","label":"Оставяш текста върху стар архивен кадър."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Променяш твърдението или добавяш позволен и възможен кадър от процеса.\nКритерият за проверка: При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Как проверяваш хуковете преди снимки?","options":[{"id":"a","label":"Сверяваш обещанието с видимото доказателство и точната аудитория."},{"id":"b","label":"Избираш най-шумния вариант."},{"id":"c","label":"Взимаш чужд хук дословно."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Сверяваш обещанието с видимото доказателство и точната аудитория.\nКритерият за проверка: При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Сценарият е списък с ефекти, без план за най-важния кадър и без проверено действие. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Приемаш файла за готов без проверка."},{"id":"b","label":"Заменяш липсващото доказателство с общо обещание."},{"id":"c","label":"Подреди причината за гледане, доказателството и действието. За всяко намерение запиши конкретен кадър и необходим звук."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Подреди причината за гледане, доказателството и действието. За всяко намерение запиши конкретен кадър и необходим звук.\nКритерият за проверка: При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s4","text":"Провери логистика, пауза за шум, реквизит и резервен кадър преди снимачния ден."},{"id":"s3","text":"Направи снимков план: широк, среден, детайл, говор/звук и преход за всяка важна сцена."},{"id":"s2","text":"Напиши хук, доказателствена сцена и действие; извади непотвърдените твърдения."},{"id":"s1","text":"Преведи целта в един проблем на зрителя и едно конкретно обещание."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Преведи целта в един проблем на зрителя и едно конкретно обещание. → Напиши хук, доказателствена сцена и действие; извади непотвърдените твърдения. → Направи снимков план: широк, среден, детайл, говор/звук и преход за всяка важна сцена. → Провери логистика, пауза за шум, реквизит и резервен кадър преди снимачния ден."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["От брифа изведи едно обещание, което може да се види или чуе. Първият кадър трябва да даде причина точният човек да остане; после покажи доказателство и реална следваща стъпка. Списъкът с кадри съществува, за да не липсва материал за смислен монтаж: номер на кадър, действие, размер, звук, място и резервен вариант.","Подреди причината за гледане, доказателството и действието. За всяко намерение запиши конкретен кадър и необходим звук.","При спрян първи кадър зрител от целевата аудитория може да предположи темата; монтажистът знае кои кадри и звуци са нужни, без да пита автора."],"nextStep":"Създай 45–75 секундно разкадровъчно решение или еквивалент за твоя формат. Предай една страница сценарий и таблица за 6–10 ключови кадъра с резервни кадри и източник на звук."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-03","title":"Record: заснеми материал, който може да се монтира","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките.","hook":"След снимките собственикът говори добре, но от фурната се чува вентилатор и нямаш чист дубъл на решаващото изречение.","estimated_minutes":50,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"След снимките собственикът говори добре, но от фурната се чува вентилатор и нямаш чист дубъл на решаващото изречение."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"На терен проверявай клиповете, а не само лампичката REC. Запиши проба, прослушай със слушалки, провери фокус, баланс на бялото и експозиция на кадъра, който ще ползваш. Пази непрекъснатостта на действието и снимай покритие, за да можеш да изрежеш паузи. При проблем спри и го поправи там; монтажът не връща липсваща дума или несъществуващ кадър."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Провери заряд, памет, микрофон, разрешения и локация; направи 10-секундна проба.\n2. Запиши основното действие и ключовото изречение с отделно внимание към звука.\n3. Снимай общ, среден и детайл плюс кадър за преход и резервен дубъл.\n4. Прегледай на място най-рисковите кадри и копирай файловете, без да изтриваш оригиналите."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"В учебната пекарна зашумялото интервю се мести до затворена врата; парният кадър остава без говор. Снимат се общ кадър на помещението, ръце при месене, детайл на кората и финален продукт. Преди да приключиш, отваряш последния дубъл и слушаш цялото обещание, не само началото."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Камерата показва правилен кадър на екрана, но микрофонът е бил изключен; екипът разбира чак в монтажа."},"after":{"label":"Поправка","text":"Направи проба с реалния източник на шум, прослушай файла и запиши резервен дубъл преди да напуснеш локацията."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Направи проба с реалния източник на шум, прослушай файла и запиши резервен дубъл преди да напуснеш локацията.\n\nСтатусът остава проба, докато не покриеш критерия: Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Сними свой вариант с телефон или камера. Запази подреден списък на използваемите клипове, проблемните клипове, поправките и проверката на звука. Не е нужен скъп комплект; нужно е да знаеш какво действително имаш."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Пази съгласието и обхвата на употреба на хората в кадър. Ако няма право за публикация, работи с друг обект или неразпознаваеми кадри."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"BBC Academy, Self Shooting: https://downloads.bbc.co.uk/academy/collegeofproduction/docs/self_shooting_ts.pdf\nAdobe, How to make a shot list: https://www.adobe.com/uk/creativecloud/video/discover/shot-list.html\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Какво проверяваш веднага след пробния запис?","options":[{"id":"a","label":"Броя кадри в секунда от менюто."},{"id":"b","label":"Реалния файл: говор, шум, фокус, експозиция и дължина."},{"id":"c","label":"Само заряда на батерията."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Реалния файл: говор, шум, фокус, експозиция и дължина.\nКритерият за проверка: Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Появява се непрекъснат шум върху ключова реплика. Как реагираш?","options":[{"id":"a","label":"Спираш, сменяш условията и записваш чист дубъл."},{"id":"b","label":"Продължаваш с надежда AI да възстанови думите."},{"id":"c","label":"Усилваш музиката върху гласа."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Спираш, сменяш условията и записваш чист дубъл.\nКритерият за проверка: Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кога е безопасно да приключиш снимачния ден?","options":[{"id":"a","label":"Когато собственикът каже, че е минало добре."},{"id":"b","label":"Веднага след последния натиснат REC."},{"id":"c","label":"След преглед на рисковите файлове и копие на оригиналите."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: След преглед на рисковите файлове и копие на оригиналите.\nКритерият за проверка: Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Камерата показва правилен кадър на екрана, но микрофонът е бил изключен; екипът разбира чак в монтажа. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Заменяш липсващото доказателство с общо обещание."},{"id":"b","label":"Направи проба с реалния източник на шум, прослушай файла и запиши резервен дубъл преди да напуснеш локацията."},{"id":"c","label":"Приемаш файла за готов без проверка."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Направи проба с реалния източник на шум, прослушай файла и запиши резервен дубъл преди да напуснеш локацията.\nКритерият за проверка: Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s3","text":"Снимай общ, среден и детайл плюс кадър за преход и резервен дубъл."},{"id":"s4","text":"Прегледай на място най-рисковите кадри и копирай файловете, без да изтриваш оригиналите."},{"id":"s1","text":"Провери заряд, памет, микрофон, разрешения и локация; направи 10-секундна проба."},{"id":"s2","text":"Запиши основното действие и ключовото изречение с отделно внимание към звука."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Провери заряд, памет, микрофон, разрешения и локация; направи 10-секундна проба. → Запиши основното действие и ключовото изречение с отделно внимание към звука. → Снимай общ, среден и детайл плюс кадър за преход и резервен дубъл. → Прегледай на място най-рисковите кадри и копирай файловете, без да изтриваш оригиналите."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["На терен проверявай клиповете, а не само лампичката REC. Запиши проба, прослушай със слушалки, провери фокус, баланс на бялото и експозиция на кадъра, който ще ползваш. Пази непрекъснатостта на действието и снимай покритие, за да можеш да изрежеш паузи. При проблем спри и го поправи там; монтажът не връща липсваща дума или несъществуващ кадър.","Направи проба с реалния източник на шум, прослушай файла и запиши резервен дубъл преди да напуснеш локацията.","Можеш да посочиш файл и timecode за всеки нужен кадър и реплика; проблемният звук или фокус са поправени преди края на снимките."],"nextStep":"Сними свой вариант с телефон или камера. Запази подреден списък на използваемите клипове, проблемните клипове, поправките и проверката на звука. Не е нужен скъп комплект; нужно е да знаеш какво действително имаш."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-04","title":"Assemble: сглоби, провери и експортирай първа версия","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени.","hook":"Готовият монтаж изглежда силен на голям монитор, но телефонът отрязва надписа, музиката прикрива говор, а цената от стария бриф още стои в кадър.","estimated_minutes":55,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Готовият монтаж изглежда силен на голям монитор, но телефонът отрязва надписа, музиката прикрива говор, а цената от стария бриф още стои в кадър."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"Монтажът е избор на доказателства, не витрина на ефекти. Подреди груб разказ, отрежи повторенията, изравни чуваемостта, направи базова цветна корекция между кадри и добави точни надписи. Раздели редакционния проект от експортирания файл и гледай именно експорта на целевото устройство. Сравнявай факти, цени и действия със свежия бриф."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Сглоби груба версия с едно обещание, доказателство и действие; запази v1.\n2. Провери говор срещу музика, цветово съвпадение, темпо и смисъл на всяко изречение.\n3. Прегледай надписите ръчно и тествай четимост в целевото съотношение на страните.\n4. Експортирай, изгледай на телефон и провери последния кадър, линк/номер и права."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"Първият монтаж на пекарната започва с хляба, а не с логото; шумният говор е заменен с чистия дубъл. Надписът „поръчай до 11:00“ се маха, докато часовете не се потвърдят. Двете версии v1 и v1-fix се пазят отделно; собственикът преглежда експорта, който реално ще се качи."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Автоматичен надпис е изписал погрешно ключова дума, но авторът е проверил само таймлайна, не експортирания файл."},"after":{"label":"Поправка","text":"Коригирай надписа по аудиото и гледай целия експортиран файл на телефон със звук и без звук."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Коригирай надписа по аудиото и гледай целия експортиран файл на телефон със звук и без звук.\n\nСтатусът остава проба, докато не покриеш критерия: Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Монтирай един завършен клип. Запази проект, сурови файлове и v1; направи отделен контролен експорт. В протокола посочи проблемен timecode и как точно си го поправил."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Когато платформата реже интерфейсно надписите, променяш безопасната зона и експортираш отново. Не приемай, че автоматичен цветен preset решава баланс между кадри."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"W3C WAI, Captions/Subtitles: https://www.w3.org/WAI/media/av/captions/\nAdobe, Export caption tracks: https://helpx.adobe.com/premiere/desktop/render-and-export/export-files/export-caption-tracks.html\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кой файл е правилният за последната проверка?","options":[{"id":"a","label":"Експортираният файл на целевото устройство, с проверен звук и надписи."},{"id":"b","label":"Само отвореният монтажен проект."},{"id":"c","label":"Снимка на таймлайна."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Експортираният файл на целевото устройство, с проверен звук и надписи.\nКритерият за проверка: Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Автоматичният надпис сменя смисъла на изречение. Какво правиш?","options":[{"id":"a","label":"Оставяш го, защото е генериран автоматично."},{"id":"b","label":"Скриваш надписа само на телефона си."},{"id":"c","label":"Сверяваш с аудиото, поправяш и експортираш отново."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Сверяваш с аудиото, поправяш и експортираш отново.\nКритерият за проверка: Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Как разбираш коя версия е одобрена?","options":[{"id":"a","label":"Пишеш „final-final“ без контрол."},{"id":"b","label":"Версия, дата, файл и конкретно потвърждение за същия експорт."},{"id":"c","label":"Последният файл в папката вероятно е верният."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Версия, дата, файл и конкретно потвърждение за същия експорт.\nКритерият за проверка: Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Автоматичен надпис е изписал погрешно ключова дума, но авторът е проверил само таймлайна, не експортирания файл. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Коригирай надписа по аудиото и гледай целия експортиран файл на телефон със звук и без звук."},{"id":"b","label":"Приемаш файла за готов без проверка."},{"id":"c","label":"Заменяш липсващото доказателство с общо обещание."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Коригирай надписа по аудиото и гледай целия експортиран файл на телефон със звук и без звук.\nКритерият за проверка: Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s4","text":"Експортирай, изгледай на телефон и провери последния кадър, линк/номер и права."},{"id":"s3","text":"Прегледай надписите ръчно и тествай четимост в целевото съотношение на страните."},{"id":"s2","text":"Провери говор срещу музика, цветово съвпадение, темпо и смисъл на всяко изречение."},{"id":"s1","text":"Сглоби груба версия с едно обещание, доказателство и действие; запази v1."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Сглоби груба версия с едно обещание, доказателство и действие; запази v1. → Провери говор срещу музика, цветово съвпадение, темпо и смисъл на всяко изречение. → Прегледай надписите ръчно и тествай четимост в целевото съотношение на страните. → Експортирай, изгледай на телефон и провери последния кадър, линк/номер и права."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["Монтажът е избор на доказателства, не витрина на ефекти. Подреди груб разказ, отрежи повторенията, изравни чуваемостта, направи базова цветна корекция между кадри и добави точни надписи. Раздели редакционния проект от експортирания файл и гледай именно експорта на целевото устройство. Сравнявай факти, цени и действия със свежия бриф.","Коригирай надписа по аудиото и гледай целия експортиран файл на телефон със звук и без звук.","Финалният експорт е четим и чуваем на целевото устройство; надписите предават действителния говор, фактите и действието са проверени."],"nextStep":"Монтирай един завършен клип. Запази проект, сурови файлове и v1; направи отделен контролен експорт. В протокола посочи проблемен timecode и как точно си го поправил."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-05","title":"Measure: публикувай или тествай с реални зрители","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение.","hook":"Видео има малко гледания и някой обявява, че хукът е лош. Но публикацията е нова, аудиторията не е ясна и част от трафика идва от платена кампания.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Видео има малко гледания и някой обявява, че хукът е лош. Но публикацията е нова, аудиторията не е ясна и част от трафика идва от платена кампания."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"Преди качване запиши версия, дата, канал, цел и наблюдавана метрика. Публикувай само с нужните права. Ако нямаш публичен канал или право на публикация, направи контролиран тест с хора от целевата аудитория и запиши точните им реакции. Различавай наблюдение, хипотеза и причинен извод; малка проба не доказва пазарен ефект. Не поставяй праг за гледания като условие за обучение."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Потвърди финалния експорт, правата, заглавие/описание и следващото действие.\n2. Запиши базова версия и условие на теста: канал, период, аудитория и трафик.\n3. Събери достъпните сигнали: реално действие, зрителски въпроси, отпадане или структурирана обратна връзка.\n4. Опиши ограниченията и една проверима хипотеза за следващата версия."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"Учебен контролиран тест: няколко души, които купуват хляб наблизо, гледат клипа без подсказване и отговарят какво се предлага и как се поръчва. Ако двама не разбират кога е готов продуктът, записваш това като наблюдение за тази малка група; не го превръщаш в процент за целия град. При реална публикация сравняваш данни едва когато са налични."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Екранна снимка с 200 гледания се нарича доказателство за продажби, без данни за поръчки."},"after":{"label":"Поправка","text":"Смени твърдението: показвай само наблюдаваната метрика и потърси реалния път до действието."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Смени твърдението: показвай само наблюдаваната метрика и потърси реалния път до действието.\n\nСтатусът остава проба, докато не покриеш критерия: Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Публикувай позволеното видео или проведи частен тест. Запиши какво точно е видял човекът, кога, по какъв канал, какво попита и кое остана неизвестно. Не събирай излишни лични данни."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"YouTube отбелязва, че данните за задържане обичайно се обработват 1–2 дни и част от отчетите изискват минимален обем гледания. Не прави дипломирането зависимо от този отчет."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"YouTube Help, Measure key moments for audience retention: https://support.google.com/youtube/answer/9314415\nYouTube Help, Decoding CTR & impressions: https://support.google.com/youtube/answer/16767369\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Можеш ли да оцениш ефекта само по броя гледания?","options":[{"id":"a","label":"Да, гледанията доказват продажби."},{"id":"b","label":"Да, ако клипът е красив."},{"id":"c","label":"Не; свържи метриката с целта, източника на трафик и действието."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Не; свържи метриката с целта, източника на трафик и действието.\nКритерият за проверка: Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Нямаш достъп до публична статистика. Какво е честният заместител?","options":[{"id":"a","label":"Публикуване на чужд материал за повече данни."},{"id":"b","label":"Частен тест с целеви зрители и ясно описани ограничения."},{"id":"c","label":"Измислена крива на задържане."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Частен тест с целеви зрители и ясно описани ограничения.\nКритерият за проверка: Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кога тълкуваш задържането в YouTube?","options":[{"id":"a","label":"Когато отчетът за конкретния клип е наличен и има достатъчен контекст."},{"id":"b","label":"Пет минути след публикация."},{"id":"c","label":"Като универсална диагноза за всяка платформа."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Когато отчетът за конкретния клип е наличен и има достатъчен контекст.\nКритерият за проверка: Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Екранна снимка с 200 гледания се нарича доказателство за продажби, без данни за поръчки. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Приемаш файла за готов без проверка."},{"id":"b","label":"Заменяш липсващото доказателство с общо обещание."},{"id":"c","label":"Смени твърдението: показвай само наблюдаваната метрика и потърси реалния път до действието."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Смени твърдението: показвай само наблюдаваната метрика и потърси реалния път до действието.\nКритерият за проверка: Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s3","text":"Събери достъпните сигнали: реално действие, зрителски въпроси, отпадане или структурирана обратна връзка."},{"id":"s4","text":"Опиши ограниченията и една проверима хипотеза за следващата версия."},{"id":"s1","text":"Потвърди финалния експорт, правата, заглавие/описание и следващото действие."},{"id":"s2","text":"Запиши базова версия и условие на теста: канал, период, аудитория и трафик."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Потвърди финалния експорт, правата, заглавие/описание и следващото действие. → Запиши базова версия и условие на теста: канал, период, аудитория и трафик. → Събери достъпните сигнали: реално действие, зрителски въпроси, отпадане или структурирана обратна връзка. → Опиши ограниченията и една проверима хипотеза за следващата версия."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["Преди качване запиши версия, дата, канал, цел и наблюдавана метрика. Публикувай само с нужните права. Ако нямаш публичен канал или право на публикация, направи контролиран тест с хора от целевата аудитория и запиши точните им реакции. Различавай наблюдение, хипотеза и причинен извод; малка проба не доказва пазарен ефект. Не поставяй праг за гледания като условие за обучение.","Смени твърдението: показвай само наблюдаваната метрика и потърси реалния път до действието.","Докладът съдържа проверими наблюдения, контекст и ограничения; няма измислени поръчки, задържане или причинно обяснение."],"nextStep":"Публикувай позволеното видео или проведи частен тест. Запиши какво точно е видял човекът, кога, по какъв канал, какво попита и кое остана неизвестно. Не събирай излишни лични данни."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-06","title":"Evolve: направи втора версия по конкретен сигнал","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник.","hook":"Хората разбират как се прави хлябът, но не разбират кога да го поръчат. Да смениш камерата няма да поправи липсващия отговор.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Хората разбират как се прави хлябът, но не разбират кога да го поръчат. Да смениш камерата няма да поправи липсващия отговор."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"Променяй едно измеримо или ясно наблюдавано място, а не целия клип наведнъж. Формулирай хипотеза, посочи timecode и направи v2. Запази v1 и сравнявай при сходни условия. Ако публикацията още няма достатъчно данни, именувай източника като малък зрителски тест. Изречението „новата версия е по-добра“ изисква нова проверка, не само нов експорт."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери едно наблюдение и timecode от реалното гледане или тест.\n2. Назови вероятна причина като хипотеза и опиши точно какво ще промениш.\n3. Експортирай v2; пази v1 и същия бриф/условия за сравнение.\n4. Провери v2 със същия въпрос и запиши какво се е подобрило, останало неясно или не е измерено."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"В учебния тест трима зрители разпознават продукта, но двама не схващат кога има наличност. На 00:32 текстът казва само „всяка сутрин“. V2 заменя текста с потвърден конкретен час или маха обещанието, ако часът варира. Новият тест отново пита как се поръчва; резултатът остава описание на малка група."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Сменяш музика, хук, цвят, кадри и CTA едновременно, после приписваш промяната в реакцията на хуковете."},"after":{"label":"Поправка","text":"Запази останалото постоянно, промени един обоснован елемент и сравни същия въпрос при сходни условия."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Запази останалото постоянно, промени един обоснован елемент и сравни същия въпрос при сходни условия.\n\nСтатусът остава проба, докато не покриеш критерия: Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Направи v2 на своя клип и кратък change log: сигнал, източник, timecode, хипотеза, промяна, проверка и ограничение. Ако не можеш да тестваш отново, отбележи v2 като хипотеза, не като доказан успех."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Кривата за задържане показва къде да гледаш, но не казва сама защо човек е напуснал. Съпостави я с кадъра, източника на трафик и реакциите."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"YouTube Help, Measure key moments for audience retention: https://support.google.com/youtube/answer/9314415\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кой е добър вход за версия 2?","options":[{"id":"a","label":"Нов preset без проверка."},{"id":"b","label":"Конкретно наблюдение с източник и място във видеото."},{"id":"c","label":"Усещане, че всичко трябва да е по-бързо."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Конкретно наблюдение с източник и място във видеото.\nКритерият за проверка: Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Сменил си пет неща наведнъж и реакцията е различна. Какво можеш да твърдиш?","options":[{"id":"a","label":"Че версията се е променила; не знаеш коя промяна е причинила реакцията."},{"id":"b","label":"Че новата камера е причината."},{"id":"c","label":"Че всички пет промени са доказано ефективни."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Че версията се е променила; не знаеш коя промяна е причинила реакцията.\nКритерият за проверка: Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кога заключаваш, че v2 е отстранила проблема?","options":[{"id":"a","label":"Щом файлът се експортира."},{"id":"b","label":"Щом авторът хареса цвета."},{"id":"c","label":"След повторна проверка със същия въпрос и ясни ограничения."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: След повторна проверка със същия въпрос и ясни ограничения.\nКритерият за проверка: Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Сменяш музика, хук, цвят, кадри и CTA едновременно, после приписваш промяната в реакцията на хуковете. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Заменяш липсващото доказателство с общо обещание."},{"id":"b","label":"Запази останалото постоянно, промени един обоснован елемент и сравни същия въпрос при сходни условия."},{"id":"c","label":"Приемаш файла за готов без проверка."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Запази останалото постоянно, промени един обоснован елемент и сравни същия въпрос при сходни условия.\nКритерият за проверка: Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s4","text":"Провери v2 със същия въпрос и запиши какво се е подобрило, останало неясно или не е измерено."},{"id":"s3","text":"Експортирай v2; пази v1 и същия бриф/условия за сравнение."},{"id":"s2","text":"Назови вероятна причина като хипотеза и опиши точно какво ще промениш."},{"id":"s1","text":"Избери едно наблюдение и timecode от реалното гледане или тест."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Избери едно наблюдение и timecode от реалното гледане или тест. → Назови вероятна причина като хипотеза и опиши точно какво ще промениш. → Експортирай v2; пази v1 и същия бриф/условия за сравнение. → Провери v2 със същия въпрос и запиши какво се е подобрило, останало неясно или не е измерено."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["Променяй едно измеримо или ясно наблюдавано място, а не целия клип наведнъж. Формулирай хипотеза, посочи timecode и направи v2. Запази v1 и сравнявай при сходни условия. Ако публикацията още няма достатъчно данни, именувай източника като малък зрителски тест. Изречението „новата версия е по-добра“ изисква нова проверка, не само нов експорт.","Запази останалото постоянно, промени един обоснован елемент и сравни същия въпрос при сходни условия.","Има две проследими версии и външен човек може да посочи коя разлика отговаря на кое наблюдение; ефектът е назован с точния си източник."],"nextStep":"Направи v2 на своя клип и кратък change log: сигнал, източник, timecode, хипотеза, промяна, проверка и ограничение. Ако не можеш да тестваш отново, отбележи v2 като хипотеза, не като доказан успех."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-07","title":"Предай проекта като проверим работен казус","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува.","hook":"Получаваш линк „final.mp4“ без бриф, без изходна версия и без права за музиката. Друг човек не може да използва или поправи проекта.","estimated_minutes":45,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Получаваш линк „final.mp4“ без бриф, без изходна версия и без права за музиката. Друг човек не може да използва или поправи проекта."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"Работният казус е доказуем маршрут: задача, ограничения, решения, v1, тест, v2, резултат и неизвестно. Подреди източниците и правата така, че друг човек да продължи, без да гадае. Избери какво е публично: портфолиото може да показва позволени кадри и анонимизиран процес, без да разкрива клиентски файлове или лични данни."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Постави брифа и началната хипотеза преди резултата.\n2. Сложи снимков план, кадри/звуци, v1 и проверка с дати и версии.\n3. Посочи v2, timecode на промяната, източник на сигнала и ограничения.\n4. Провери лицензите, съгласието и коя версия е разрешена за външно показване."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"Казусът за учебната пекарна честно казва „симулация“ и показва собствен клип, списък с кадри, обобщени реакции от малък тест и промяната от v1 към v2. Не включва непотвърдено лого, реален телефон или фалшиви продажби. Ако е клиентски проект, папката за предаване и публичното портфолио имат различен достъп."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Портфолиото твърди „удвоих поръчките“, а единственото налично доказателство е анкета с няколко зрители."},"after":{"label":"Поправка","text":"Покажи точния наблюдаван резултат и какво не е измерено; махни причинното бизнес твърдение."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Покажи точния наблюдаван резултат и какво не е измерено; махни причинното бизнес твърдение.\n\nСтатусът остава проба, докато не покриеш критерия: Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Подреди една страница казус и работна папка: бриф, права, сурово/подбрано, проект, v1, тест, v2, финален експорт, следваща стъпка. Направи отделна публична версия само с разрешено съдържание."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Раздели учебен, клиентски и публичен вариант на историята. Не приписвай симулирани продажби или аудитория на реален бизнес."},"points":1,"required":false},{"position":10,"block_key":"optional_portfolio","block_type":"submission","title":"Линк към позволеното портфолио (по избор)","content":{"prompt":"Ако имаш право да покажеш проекта, можеш да добавиш линк към позволената версия или PDF с процеса. Този линк не се оценява автоматично и не влияе на изпита."},"points":0,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"Your Europe, Copyright in the EU: https://europa.eu/youreurope/business/growing/protecting-intellectual-property/copyright/index_en.htm\nW3C WAI, Captions/Subtitles: https://www.w3.org/WAI/media/av/captions/\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":12,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Какво прави казуса проверим?","options":[{"id":"a","label":"Версии, бриф, източник на сигнал, права и ограничения."},{"id":"b","label":"Само най-красивият кадър."},{"id":"c","label":"Голямо число без източник."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Версии, бриф, източник на сигнал, права и ограничения.\nКритерият за проверка: Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Нямаш разрешение за публично показване на клиентската медия. Какво правиш?","options":[{"id":"a","label":"Публикуваш и махаш след оплакване."},{"id":"b","label":"Приемаш, че платената работа автоматично дава право за портфолио."},{"id":"c","label":"Държиш я частна и показваш само позволен, анонимизиран процес."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Държиш я частна и показваш само позволен, анонимизиран процес.\nКритерият за проверка: Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Какво предаваш на колега за продължение?","options":[{"id":"a","label":"Снимка на статистика без дата."},{"id":"b","label":"Одобрената версия, изходници, бриф, права, известни проблеми и следващи стъпки."},{"id":"c","label":"Само експорт с име final."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Одобрената версия, изходници, бриф, права, известни проблеми и следващи стъпки.\nКритерият за проверка: Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Портфолиото твърди „удвоих поръчките“, а единственото налично доказателство е анкета с няколко зрители. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Покажи точния наблюдаван резултат и какво не е измерено; махни причинното бизнес твърдение."},{"id":"b","label":"Приемаш файла за готов без проверка."},{"id":"c","label":"Заменяш липсващото доказателство с общо обещание."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Покажи точния наблюдаван резултат и какво не е измерено; махни причинното бизнес твърдение.\nКритерият за проверка: Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s3","text":"Посочи v2, timecode на промяната, източник на сигнала и ограничения."},{"id":"s4","text":"Провери лицензите, съгласието и коя версия е разрешена за външно показване."},{"id":"s1","text":"Постави брифа и началната хипотеза преди резултата."},{"id":"s2","text":"Сложи снимков план, кадри/звуци, v1 и проверка с дати и версии."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Постави брифа и началната хипотеза преди резултата. → Сложи снимков план, кадри/звуци, v1 и проверка с дати и версии. → Посочи v2, timecode на промяната, източник на сигнала и ограничения. → Провери лицензите, съгласието и коя версия е разрешена за външно показване."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["Работният казус е доказуем маршрут: задача, ограничения, решения, v1, тест, v2, резултат и неизвестно. Подреди източниците и правата така, че друг човек да продължи, без да гадае. Избери какво е публично: портфолиото може да показва позволени кадри и анонимизиран процес, без да разкрива клиентски файлове или лични данни.","Покажи точния наблюдаван резултат и какво не е измерено; махни причинното бизнес твърдение.","Човек извън проекта намира за минута брифа, одобрения файл, източника на наблюдението и коя версия има право да публикува."],"nextStep":"Подреди една страница казус и работна папка: бриф, права, сурово/подбрано, проект, v1, тест, v2, финален експорт, следваща стъпка. Направи отделна публична версия само с разрешено съдържание."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-08","title":"Провери проекта преди изпитите и посочи слабите места","subtitle":"Финален проект по FRAME: реално решение, проверка и поправка","objective":"Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи.","hook":"Имаш завършен клип, но в контролния преглед излизат стара версия на телефона, непроверен надпис и липсваща дата на теста.","estimated_minutes":35,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще завършиш","content":{"body":"Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Работната ситуация","content":{"body":"Имаш завършен клип, но в контролния преглед излизат стара версия на телефона, непроверен надпис и липсваща дата на теста."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад действието","content":{"body":"Финалната проверка търси най-скъпата грешка, а не декоративен пропуск. Минаваш проекта по веригата: верен бриф → нужни кадри и звук → проверен експорт → позволена публикация/тест → честна поправка. За всяка липса избери действие: поправи сега, изчакай разрешение, или остави ясно означено ограничение. Отговорите в изпитите ще търсят тези решения, а не запаметени имена на менюта."},"points":2,"required":true},{"position":3,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Отвори именно файла, който зрителят или клиентът ще получи.\n2. Свери факт, звук, четимост, права и действие по пет конкретни точки.\n3. Свери v1, наблюдението и v2; маркирай симулация и неизмерим резултат.\n4. Направи списък: готово, блокирано, за повторна проверка — с отговорник и следваща стъпка."},"points":2,"required":true},{"position":4,"block_key":"case","block_type":"example","title":"Как би работил професионалист","content":{"body":"За учебния казус финалната папка е пълна, но номерът за поръчка е примерен. Статусът е „демо, непубликуваемо с този номер“. Ако собственикът потвърди номер и права, правиш нов експорт, гледаш го на телефон и едва после сменяш статуса. Не замаскираш празнината с „готово“."},"points":2,"required":true},{"position":5,"block_key":"repair","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Грешка","text":"Оценяваш клипа само по визуален вкус и допускаш невярно обещание да остане в финалния файл."},"after":{"label":"Поправка","text":"Провери истинността и правата първо; поправи блокиращото, после решавай фини промени по ритъм и стил."}},"points":2,"required":true},{"position":6,"block_key":"diagnosis","block_type":"rich_text","title":"Ако условията се променят","content":{"body":"Първо виж кой факт се е променил. Запази стария файл и брифа, за да не приписваш новото решение на стари условия. Провери истинността и правата първо; поправи блокиращото, после решавай фини промени по ритъм и стил.\n\nСтатусът остава проба, докато не покриеш критерия: Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Твоята работа","content":{"body":"Направи вътрешен одит на проекта с конкретни timecode и решение за всеки проблем. Ако нещо е недостъпно, запиши честно статуса и не наричай проекта публикуван."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Сам провери резултата","content":{"body":"Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи.\n\nЗапиши кое е реално проверено и кое е само допускане. Пази изходната и променената версия. Не включвай човек, актив или клиентски материал без право за тази употреба."},"points":1,"required":true},{"position":9,"block_key":"field_note","block_type":"rich_text","title":"Граничен случай","content":{"body":"Периодичните тестове след този урок проверяват решения от всичките 14 предишни модула; общият изпит свързва тези решения с финалния проект."},"points":1,"required":false},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Проверен професионален източник","content":{"body":"W3C WAI, Captions/Subtitles: https://www.w3.org/WAI/media/av/captions/\nBBC Academy, Self Shooting: https://downloads.bbc.co.uk/academy/collegeofproduction/docs/self_shooting_ts.pdf\nИзползвай принципа и провери актуалните условия на конкретната платформа или проекта."},"points":0,"required":false},{"position":11,"block_key":"decision","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"Кой пропуск спира публикацията?","options":[{"id":"a","label":"Преходът не е достатъчно артистичен."},{"id":"b","label":"Името на проекта е кратко."},{"id":"c","label":"Непотвърдено продуктово обещание или липсващо право за кадър."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Непотвърдено продуктово обещание или липсващо право за кадър.\nКритерият за проверка: Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"edge","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Номерът в клипа е примерен. Какъв е статусът?","options":[{"id":"a","label":"Готово, ако екранът изглежда добре."},{"id":"b","label":"Учебна версия; чака потвърждение и нов проверен експорт."},{"id":"c","label":"Публикуваемо, защото цифрите приличат на телефон."}]},"points":4,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тук решението е: Учебна версия; чака потвърждение и нов проверен експорт.\nКритерият за проверка: Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"measure","block_type":"quiz","title":"Решение в реална ситуация","content":{"question":"За какво служи финалният одит?","options":[{"id":"a","label":"Да свърже доказателство, ограничение и следващо действие преди предаване."},{"id":"b","label":"Да добави още графични ефекти."},{"id":"c","label":"Да замести теста с мнението на автора."}]},"points":4,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тук решението е: Да свърже доказателство, ограничение и следващо действие преди предаване.\nКритерият за проверка: Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"repair_choice","block_type":"scenario","title":"Решение в реална ситуация","content":{"prompt":"Виждаш този проблем: Оценяваш клипа само по визуален вкус и допускаш невярно обещание да остане в финалния файл. Коя е следващата работна стъпка?","options":[{"id":"a","label":"Приемаш файла за готов без проверка."},{"id":"b","label":"Заменяш липсващото доказателство с общо обещание."},{"id":"c","label":"Провери истинността и правата първо; поправи блокиращото, после решавай фини промени по ритъм и стил."}]},"points":4,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тук решението е: Провери истинността и правата първо; поправи блокиращото, после решавай фини промени по ритъм и стил.\nКритерият за проверка: Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence","block_type":"sequence_sort","title":"Подреди действията","content":{"instruction":"Сложи проверката преди финалното предаване.","items":[{"id":"s4","text":"Направи списък: готово, блокирано, за повторна проверка — с отговорник и следваща стъпка."},{"id":"s3","text":"Свери v1, наблюдението и v2; маркирай симулация и неизмерим резултат."},{"id":"s2","text":"Свери факт, звук, четимост, права и действие по пет конкретни точки."},{"id":"s1","text":"Отвори именно файла, който зрителят или клиентът ще получи."}]},"points":4,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът пази най-рисковите зависимости: Отвори именно файла, който зрителят или клиентът ще получи. → Свери факт, звук, четимост, права и действие по пет конкретни точки. → Свери v1, наблюдението и v2; маркирай симулация и неизмерим резултат. → Направи списък: готово, блокирано, за повторна проверка — с отговорник и следваща стъпка."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво остава в проекта","content":{"takeaways":["Финалната проверка търси най-скъпата грешка, а не декоративен пропуск. Минаваш проекта по веригата: верен бриф → нужни кадри и звук → проверен експорт → позволена публикация/тест → честна поправка. За всяка липса избери действие: поправи сега, изчакай разрешение, или остави ясно означено ограничение. Отговорите в изпитите ще търсят тези решения, а не запаметени имена на менюта.","Провери истинността и правата първо; поправи блокиращото, после решавай фини промени по ритъм и стил.","Всеки критичен пропуск има наблюдение, приоритет, отговорник и действие; готовата версия отговаря на реалния бриф и може да се проследи."],"nextStep":"Направи вътрешен одит на проекта с конкретни timecode и решение за всеки проблем. Ако нещо е недостъпно, запиши честно статуса и не наричай проекта публикуван."},"points":1,"required":true}]},{"module_id":"s02-m15","lesson_id":"pv15-09","title":"Изпит 1: стратегия, послание, камера и светлина","subtitle":"Общ практически изпит по решения, а не тест по определения","objective":"Решаваш обвързани задачи от 01, 02, 03, 04 с поне 80% в един опит.","hook":"Сервиз за велосипеди иска видео за сезонна проверка. Има един ден за снимане, работилница с прозорец и стар клип с много гледания, но малко запитвания. Раздели впечатлението от доказателството и вземи решения, които могат да се изпълнят.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво доказваш","content":{"body":"Прилагаш работни решения от 01, 02, 03, 04. Минимум 80% верни решения в общ опит. При непреминат изпит виждаш темите за повторение, без готов ключ."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Казусът","content":{"body":"Сервиз за велосипеди иска видео за сезонна проверка. Има един ден за снимане, работилница с прозорец и стар клип с много гледания, но малко запитвания. Раздели впечатлението от доказателството и вземи решения, които могат да се изпълнят."},"points":1,"required":true},{"position":2,"block_key":"read_case","block_type":"case_study","title":"Прочети условията, преди да отговаряш","content":{"body":"Сервиз за велосипеди иска видео за сезонна проверка. Има един ден за снимане, работилница с прозорец и стар клип с много гледания, но малко запитвания. Раздели впечатлението от доказателството и вземи решения, които могат да се изпълнят.\n\nНе добавяй права, резултати или ресурси, които брифът не дава."},"points":1,"required":true},{"position":3,"block_key":"prepare","block_type":"rich_text","title":"Провери своя проект преди изпита","content":{"body":"Преди изпита разгледай свой стар клип: запиши за кого е, къде зрителят губи нишката, кое твърдение доказва кадърът и как светлината и камерата помагат или пречат. Не е нужно да предаваш свободен текст."},"points":2,"required":true},{"position":4,"block_key":"rules","block_type":"rich_text","title":"Как се оценява","content":{"body":"Отговори на всички въпроси и предай целия изпит наведнъж. Сървърът оценява общия опит; успехът е от 80% нагоре. Ако не достигнеш прага, ще видиш кои модули да повториш. Грешните въпроси не показват верния избор. След повторение можеш да предадеш нов пълен опит. Това е изпит на решения; качеството и авторството на твоя видеопроект не се оценяват само от теста."},"points":1,"required":true},{"position":5,"block_key":"summary","block_type":"summary","title":"Какво да направиш след резултата","content":{"takeaways":["Отделяй факт от допускане.","Поправяй с доказателство и timecode, когато можеш.","Резултат под 80% води до повторение на посочените теми."],"nextStep":"Прегледай работата си и премини към изпита като един цял опит."},"points":1,"required":true},{"position":6,"block_key":"exam","block_type":"course_exam","title":"Предай целия изпит","content":{"introduction":"Избери най-защитимото действие при дадените условия.","questions":[{"id":"q01","moduleId":"s02-m01","prompt":"Стар клип има много гледания, но не знаеш откъде идват. Кое е първото смислено действие?","options":[{"id":"a","label":"Определи целта и провери източника на трафик и следващото действие."},{"id":"b","label":"Повтори същия клип с нова камера."},{"id":"c","label":"Обяви, че стратегията е успешна само по гледания."}]},{"id":"q02","moduleId":"s02-m01","prompt":"Коя хипотеза можеш да провериш с кратък тест?","options":[{"id":"a","label":"Дали алгоритъмът ще хареса автора."},{"id":"b","label":"Дали видеото ще стане вирусно без контекст."},{"id":"c","label":"Дали целевият зрител разбира услугата и следващата стъпка."}]},{"id":"q03","moduleId":"s02-m01","prompt":"Имаш три content pillar-а, но нито един не води до реален въпрос на клиента. Какво поправяш?","options":[{"id":"a","label":"Преименуваш рубриките без промяна в съдържанието."},{"id":"b","label":"Свързваш рубриките с повтарящи се клиентски задачи и проверима цел."},{"id":"c","label":"Публикуваш още от същото по график."}]},{"id":"q04","moduleId":"s02-m02","prompt":"Хукът обещава ремонт за 10 минути, а техникът не може да го гарантира. Кой ход е правилен?","options":[{"id":"a","label":"Смени обещанието с вярно и покажи реалната проверка."},{"id":"b","label":"Остави обещанието, защото хукът е силен."},{"id":"c","label":"Скрий ограничението чак в коментарите."}]},{"id":"q05","moduleId":"s02-m02","prompt":"Клипът обяснява пет услуги и зрителят не помни нито една. Какво правиш?","options":[{"id":"a","label":"Ускори гласа, за да се съберат всички."},{"id":"b","label":"Добави още шест надписа."},{"id":"c","label":"Избери една задача, едно доказателство и едно действие за този клип."}]},{"id":"q06","moduleId":"s02-m02","prompt":"Кое CTA пасва на видео за проверка на велосипед?","options":[{"id":"a","label":"Фалшиво обратно броене до несъществуваща оферта."},{"id":"b","label":"Ясна стъпка за записване, която действително работи и е показана в края."},{"id":"c","label":"Неясно „последвай за още“ без връзка с целта."}]},{"id":"q07","moduleId":"s02-m03","prompt":"Снимаш движение на колело и при смяна на кадри посоката се обърква. Какво проверяваш?","options":[{"id":"a","label":"Линията на действие, посоката на движение и покритието между кадрите."},{"id":"b","label":"Само резолюцията на камерата."},{"id":"c","label":"Цвета на надписа."}]},{"id":"q08","moduleId":"s02-m03","prompt":"Автоматичният баланс на бялото сменя цвета при всеки дубъл. Какъв е ходът?","options":[{"id":"a","label":"Остави разликата за случаен preset."},{"id":"b","label":"Смени само FPS."},{"id":"c","label":"Заключи или съгласувай баланса за тази светлина и направи проба."}]},{"id":"q09","moduleId":"s02-m03","prompt":"Детайлът на спирачките е неясен. Какво проверяваш преди още дубъл?","options":[{"id":"a","label":"Дали имаш най-скъпия обектив."},{"id":"b","label":"Реалния фокус и експозиция на детайла в записания файл."},{"id":"c","label":"Броя последователи на сервиза."}]},{"id":"q10","moduleId":"s02-m04","prompt":"Лицето до прозореца е тъмно, фонът е ярък. Какво променяш първо?","options":[{"id":"a","label":"Разположението спрямо прозореца и експозицията на лицето."},{"id":"b","label":"Добавяш оранжев LUT преди да снимаш."},{"id":"c","label":"Увеличаваш звука."}]},{"id":"q11","moduleId":"s02-m04","prompt":"Два кадъра имат различен кожен тон след монтажа. Кое е правилното действие?","options":[{"id":"a","label":"Сложи различен стил на всеки кадър."},{"id":"b","label":"Приеми, че зрителят няма да забележи."},{"id":"c","label":"Свери експозиция и баланс, после направи цветово съвпадение."}]},{"id":"q12","moduleId":"s02-m04","prompt":"Една от лампите примигва в записания файл. Кога решаваш проблема?","options":[{"id":"a","label":"Като добавиш повече преходи в монтажа."},{"id":"b","label":"На място с пробен запис и промяна на условията."},{"id":"c","label":"След публикация с текстово извинение."}]}],"minimumPercent":80},"points":36,"required":true,"answer_key":{"answers":{"q01":"a","q02":"c","q03":"b","q04":"a","q05":"c","q06":"b","q07":"a","q08":"c","q09":"b","q10":"a","q11":"c","q12":"b"}},"feedback":{"explanation":"Виж темите за повторение по-долу. Провери логиката спрямо собствения си проект."},"scoring":{"mode":"aggregate","minimumPercent":80}}]},{"module_id":"s02-m15","lesson_id":"pv15-10","title":"Изпит 2: звук, снимачен ден, телефон и организация","subtitle":"Общ практически изпит по решения, а не тест по определения","objective":"Решаваш обвързани задачи от 05, 06, 07, 08 с поне 80% в един опит.","hook":"Снимаш три кратки видеа в малък магазин. Продавачът има 40 минути, климатикът шуми, осветлението се мести, а ти разполагаш с телефон и един външен микрофон. Покажи кой риск се решава на терен и кой може да чака монтажа.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво доказваш","content":{"body":"Прилагаш работни решения от 05, 06, 07, 08. Минимум 80% верни решения в общ опит. При непреминат изпит виждаш темите за повторение, без готов ключ."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Казусът","content":{"body":"Снимаш три кратки видеа в малък магазин. Продавачът има 40 минути, климатикът шуми, осветлението се мести, а ти разполагаш с телефон и един външен микрофон. Покажи кой риск се решава на терен и кой може да чака монтажа."},"points":1,"required":true},{"position":2,"block_key":"read_case","block_type":"case_study","title":"Прочети условията, преди да отговаряш","content":{"body":"Снимаш три кратки видеа в малък магазин. Продавачът има 40 минути, климатикът шуми, осветлението се мести, а ти разполагаш с телефон и един външен микрофон. Покажи кой риск се решава на терен и кой може да чака монтажа.\n\nНе добавяй права, резултати или ресурси, които брифът не дава."},"points":1,"required":true},{"position":3,"block_key":"prepare","block_type":"rich_text","title":"Провери своя проект преди изпита","content":{"body":"Направи 10-секундна проба със собствения си телефон и слушалки. Изгради списък за снимки и структура на папки. Първо реши проблемите, които не могат да се възстановят по-късно."},"points":2,"required":true},{"position":4,"block_key":"rules","block_type":"rich_text","title":"Как се оценява","content":{"body":"Отговори на всички въпроси и предай целия изпит наведнъж. Сървърът оценява общия опит; успехът е от 80% нагоре. Ако не достигнеш прага, ще видиш кои модули да повториш. Грешните въпроси не показват верния избор. След повторение можеш да предадеш нов пълен опит. Това е изпит на решения; качеството и авторството на твоя видеопроект не се оценяват само от теста."},"points":1,"required":true},{"position":5,"block_key":"summary","block_type":"summary","title":"Какво да направиш след резултата","content":{"takeaways":["Отделяй факт от допускане.","Поправяй с доказателство и timecode, когато можеш.","Резултат под 80% води до повторение на посочените теми."],"nextStep":"Прегледай работата си и премини към изпита като един цял опит."},"points":1,"required":true},{"position":6,"block_key":"exam","block_type":"course_exam","title":"Предай целия изпит","content":{"introduction":"Избери най-защитимото действие при дадените условия.","questions":[{"id":"q01","moduleId":"s02-m05","prompt":"Гласът е чист без музика, но думите се губят след добавянето ѝ. Какво правиш?","options":[{"id":"a","label":"Усили и двата трака еднакво."},{"id":"b","label":"Добави още субтитри вместо аудио проверка."},{"id":"c","label":"Свали музиката спрямо гласа и прослушай финалния експорт."}]},{"id":"q02","moduleId":"s02-m05","prompt":"Лавалиерът е близо до устата, но дрехата постоянно го търка. Какво проверяваш?","options":[{"id":"a","label":"Единствено шумопотискане след снимките."},{"id":"b","label":"Монтаж и позиция на микрофона с реална проба в движение."},{"id":"c","label":"Само дали батерията е пълна."}]},{"id":"q03","moduleId":"s02-m05","prompt":"Кой запис е надеждна резервна защита за важна реплика?","options":[{"id":"a","label":"Допълнителен чист дубъл, прослушан на място."},{"id":"b","label":"Обещание, че AI ще възстанови липсващи думи."},{"id":"c","label":"Стокова музика под повредения говор."}]},{"id":"q04","moduleId":"s02-m06","prompt":"Продавачът има малко време. Как подреждаш снимането?","options":[{"id":"a","label":"Първо всички декоративни кадри."},{"id":"b","label":"Снимаш на случаен принцип, докато му свърши времето."},{"id":"c","label":"Първо незаменимите реплики и действия, после покритие и резерви."}]},{"id":"q05","moduleId":"s02-m06","prompt":"Локацията е различна от снимките в брифа. Какво правиш?","options":[{"id":"a","label":"Обещаваш поправка на всичко в монтажа."},{"id":"b","label":"Проверяваш на място звук, светлина, безопасност и новите ограничения."},{"id":"c","label":"Запазваш плана без проба."}]},{"id":"q06","moduleId":"s02-m06","prompt":"Човекът пред камера повтаря текст като робот. Каква е добра режисьорска стъпка?","options":[{"id":"a","label":"Дай му кратък конкретен въпрос и запази смисъла в собствения му глас."},{"id":"b","label":"Карай го да говори два пъти по-бързо."},{"id":"c","label":"Замени гласа със синтетичен без съгласие."}]},{"id":"q07","moduleId":"s02-m07","prompt":"Телефонът снима добре, но записът от вградения микрофон е далечен. Коя покупка или промяна е първа?","options":[{"id":"a","label":"Купи гимбъл за гладък преход."},{"id":"b","label":"Смени телефона заради резолюцията."},{"id":"c","label":"Доближи или добави подходящ микрофон и направи звуков тест."}]},{"id":"q08","moduleId":"s02-m07","prompt":"HDR клипът изглежда добре на телефона, но странно след експорт. Какво проверяваш?","options":[{"id":"a","label":"Броя хаштагове."},{"id":"b","label":"Цветовия работен поток и реалния експорт на целевото устройство."},{"id":"c","label":"Само капацитета на картата."}]},{"id":"q09","moduleId":"s02-m07","prompt":"Нямаш гимбъл за кадъра. Кое е разумно?","options":[{"id":"a","label":"Стабилен статичен или опрян кадър, ако покрива целта."},{"id":"b","label":"Отказ от целия проект."},{"id":"c","label":"Движение на ръка на всяка цена."}]},{"id":"q10","moduleId":"s02-m08","prompt":"Снимаш серия от осем клипа. Как спестяваш смени на светлина?","options":[{"id":"a","label":"Пренареждаш лампите след всеки кадър без план."},{"id":"b","label":"Пропускаш пробите за звук."},{"id":"c","label":"Групираш по локация и настройка, като пазиш проверка за всеки сценарий."}]},{"id":"q11","moduleId":"s02-m08","prompt":"Откриваш два файла с еднакво име от различни телефони. Как пазиш проекта?","options":[{"id":"a","label":"Оставяш само клиповете в чата."},{"id":"b","label":"Копираш в ясни папки по камера и дата, проверяваш файловете и държиш резервно копие."},{"id":"c","label":"Изтриваш единия на случаен принцип."}]},{"id":"q12","moduleId":"s02-m08","prompt":"Кой е правилният момент за изтриване на оригиналите от картата?","options":[{"id":"a","label":"След проверени копия и съгласуван план за съхранение."},{"id":"b","label":"Веднага след като някой каже „снимано“."},{"id":"c","label":"Щом видиш миниатюра в папката."}]}],"minimumPercent":80},"points":36,"required":true,"answer_key":{"answers":{"q01":"c","q02":"b","q03":"a","q04":"c","q05":"b","q06":"a","q07":"c","q08":"b","q09":"a","q10":"c","q11":"b","q12":"a"}},"feedback":{"explanation":"Виж темите за повторение по-долу. Провери логиката спрямо собствения си проект."},"scoring":{"mode":"aggregate","minimumPercent":80}}]},{"module_id":"s02-m15","lesson_id":"pv15-11","title":"Изпит 3: монтаж, разпространение, аналитика и AI","subtitle":"Общ практически изпит по решения, а не тест по определения","objective":"Решаваш обвързани задачи от 09, 10, 11, 12 с поне 80% в един опит.","hook":"Видеото е монтирано и пуснато. Надписите са неточни, заглавието обещава тема, която идва едва в края, а AI резюмето е добавило несъществуващ цитат. Публикацията има неравномерен трафик. Подреди поправките по риск и доказателство.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво доказваш","content":{"body":"Прилагаш работни решения от 09, 10, 11, 12. Минимум 80% верни решения в общ опит. При непреминат изпит виждаш темите за повторение, без готов ключ."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Казусът","content":{"body":"Видеото е монтирано и пуснато. Надписите са неточни, заглавието обещава тема, която идва едва в края, а AI резюмето е добавило несъществуващ цитат. Публикацията има неравномерен трафик. Подреди поправките по риск и доказателство."},"points":1,"required":true},{"position":2,"block_key":"read_case","block_type":"case_study","title":"Прочети условията, преди да отговаряш","content":{"body":"Видеото е монтирано и пуснато. Надписите са неточни, заглавието обещава тема, която идва едва в края, а AI резюмето е добавило несъществуващ цитат. Публикацията има неравномерен трафик. Подреди поправките по риск и доказателство.\n\nНе добавяй права, резултати или ресурси, които брифът не дава."},"points":1,"required":true},{"position":3,"block_key":"prepare","block_type":"rich_text","title":"Провери своя проект преди изпита","content":{"body":"Отвори свой експорт на телефон със звук и без звук. Свери заглавие, първи кадър, надписи, твърдения, източници на трафик и въпросите на зрителите, преди да решиш какво да сменяш."},"points":2,"required":true},{"position":4,"block_key":"rules","block_type":"rich_text","title":"Как се оценява","content":{"body":"Отговори на всички въпроси и предай целия изпит наведнъж. Сървърът оценява общия опит; успехът е от 80% нагоре. Ако не достигнеш прага, ще видиш кои модули да повториш. Грешните въпроси не показват верния избор. След повторение можеш да предадеш нов пълен опит. Това е изпит на решения; качеството и авторството на твоя видеопроект не се оценяват само от теста."},"points":1,"required":true},{"position":5,"block_key":"summary","block_type":"summary","title":"Какво да направиш след резултата","content":{"takeaways":["Отделяй факт от допускане.","Поправяй с доказателство и timecode, когато можеш.","Резултат под 80% води до повторение на посочените теми."],"nextStep":"Прегледай работата си и премини към изпита като един цял опит."},"points":1,"required":true},{"position":6,"block_key":"exam","block_type":"course_exam","title":"Предай целия изпит","content":{"introduction":"Избери най-защитимото действие при дадените условия.","questions":[{"id":"q01","moduleId":"s02-m09","prompt":"Монтажът прескача от говор към детайл, но фразата се прекъсва неестествено. Какво проверяваш?","options":[{"id":"a","label":"Добави flash преход."},{"id":"b","label":"Връзката между звуковия и визуалния преход; използвай покритие и плавен звуков монтаж."},{"id":"c","label":"Само скоростта на детайлния кадър."}]},{"id":"q02","moduleId":"s02-m09","prompt":"Клипът е цветно красив, но тоновете скачат между два съседни кадъра. Какъв е редът?","options":[{"id":"a","label":"Изравни експозиция и баланс между кадрите, после приложи стил."},{"id":"b","label":"Добави още по-силен LUT."},{"id":"c","label":"Смени музиката."}]},{"id":"q03","moduleId":"s02-m09","prompt":"Къде проверяваш надписите след експорта?","options":[{"id":"a","label":"Само в автоматичния транскрипт."},{"id":"b","label":"Само в първите две секунди."},{"id":"c","label":"В целия готов файл на целевия екран, сверени с казаното."}]},{"id":"q04","moduleId":"s02-m10","prompt":"Заглавието обещава съвет, който видеото не дава. Как го поправяш?","options":[{"id":"a","label":"Скрий разминаването в описанието."},{"id":"b","label":"Пренапиши го според действителното съдържание или поправи видеото."},{"id":"c","label":"Остави го за повече кликове."}]},{"id":"q05","moduleId":"s02-m10","prompt":"Как избираш формат за различни платформи?","options":[{"id":"a","label":"Проверяваш кадриране, надписи и действие във всяка реална версия."},{"id":"b","label":"Качваш една и съща версия навсякъде без преглед."},{"id":"c","label":"Само променяш името на файла."}]},{"id":"q06","moduleId":"s02-m10","prompt":"Миниатюрата е четима, но показва несъществуващ резултат. Какво правиш?","options":[{"id":"a","label":"Запазваш я, ако CTR е висок."},{"id":"b","label":"Слагаш още по-голямо число."},{"id":"c","label":"Сменяш обещанието с кадър и текст, които видеото действително подкрепя."}]},{"id":"q07","moduleId":"s02-m11","prompt":"Появява се спад на 00:20 в отчет за задържане. Кое следва?","options":[{"id":"a","label":"Изтриваш всички първи 20 секунди без преглед."},{"id":"b","label":"Гледаш този момент, източниците на трафик и какво е обещано преди него."},{"id":"c","label":"Знаеш със сигурност, че причината е камерата."}]},{"id":"q08","moduleId":"s02-m11","prompt":"CTR е различен при препоръчани и външен трафик. Как сравняваш?","options":[{"id":"a","label":"По сходен източник и контекст, без да обединяваш двата процента в диагноза."},{"id":"b","label":"Само по по-високото число."},{"id":"c","label":"Сравняваш с несвързан канал без условия."}]},{"id":"q09","moduleId":"s02-m11","prompt":"Данните са малко и отчетът за задържане още липсва. Какво докладваш?","options":[{"id":"a","label":"Точна крива на задържане по интуиция."},{"id":"b","label":"Окончателна присъда за качеството."},{"id":"c","label":"Наличните наблюдения и кога ще провериш пак; не измисляш липсващ отчет."}]},{"id":"q10","moduleId":"s02-m12","prompt":"AI резюмето добавя цитат, който никой не е казал. Какво правиш?","options":[{"id":"a","label":"Приписваш го на анонимен клиент."},{"id":"b","label":"Връщаш се към записа, махаш невярното и проверяваш всички твърдения."},{"id":"c","label":"Оставяш цитата, ако звучи добре."}]},{"id":"q11","moduleId":"s02-m12","prompt":"Можеш ли да използваш синтетичен глас на клиент без разрешение?","options":[{"id":"a","label":"Не; провери право и съгласие, а при липса смени подхода."},{"id":"b","label":"Да, ако гласът звучи реалистично."},{"id":"c","label":"Да, ако клипът е кратък."}]},{"id":"q12","moduleId":"s02-m12","prompt":"AI е изчистил шума, но е променил дума в ключова реплика. Какво е приоритетно?","options":[{"id":"a","label":"Приеми промяната, ако звукът е по-чист."},{"id":"b","label":"Скрий разликата под музика."},{"id":"c","label":"Върни вярната реплика и провери експорта срещу оригинала."}]}],"minimumPercent":80},"points":36,"required":true,"answer_key":{"answers":{"q01":"b","q02":"a","q03":"c","q04":"b","q05":"a","q06":"c","q07":"b","q08":"a","q09":"c","q10":"b","q11":"a","q12":"c"}},"feedback":{"explanation":"Виж темите за повторение по-долу. Провери логиката спрямо собствения си проект."},"scoring":{"mode":"aggregate","minimumPercent":80}}]},{"module_id":"s02-m15","lesson_id":"pv15-12","title":"Изпит 4: клиентска работа, собствен стил и одит","subtitle":"Общ практически изпит по решения, а не тест по определения","objective":"Решаваш обвързани задачи от 13, 14 с поне 80% в един опит.","hook":"Клиент иска четири версии до утре, но плаща за една и не е дал права за музиката. Структура от чужд успешен клип му харесва. Твоят одит показва неясен CTA и силен собствен кадър. Вземи решения за обхват, права и истинска поправка.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво доказваш","content":{"body":"Прилагаш работни решения от 13, 14. Минимум 80% верни решения в общ опит. При непреминат изпит виждаш темите за повторение, без готов ключ."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Казусът","content":{"body":"Клиент иска четири версии до утре, но плаща за една и не е дал права за музиката. Структура от чужд успешен клип му харесва. Твоят одит показва неясен CTA и силен собствен кадър. Вземи решения за обхват, права и истинска поправка."},"points":1,"required":true},{"position":2,"block_key":"read_case","block_type":"case_study","title":"Прочети условията, преди да отговаряш","content":{"body":"Клиент иска четири версии до утре, но плаща за една и не е дал права за музиката. Структура от чужд успешен клип му харесва. Твоят одит показва неясен CTA и силен собствен кадър. Вземи решения за обхват, права и истинска поправка.\n\nНе добавяй права, резултати или ресурси, които брифът не дава."},"points":1,"required":true},{"position":3,"block_key":"prepare","block_type":"rich_text","title":"Провери своя проект преди изпита","content":{"body":"Свери своя бриф и оферта с доставките, часовете и правата. Одитирай собствен клип по timecode, отдели силната сцена от копирания шаблон и покажи коя версия би предал."},"points":2,"required":true},{"position":4,"block_key":"rules","block_type":"rich_text","title":"Как се оценява","content":{"body":"Отговори на всички въпроси и предай целия изпит наведнъж. Сървърът оценява общия опит; успехът е от 80% нагоре. Ако не достигнеш прага, ще видиш кои модули да повториш. Грешните въпроси не показват верния избор. След повторение можеш да предадеш нов пълен опит. Това е изпит на решения; качеството и авторството на твоя видеопроект не се оценяват само от теста."},"points":1,"required":true},{"position":5,"block_key":"summary","block_type":"summary","title":"Какво да направиш след резултата","content":{"takeaways":["Отделяй факт от допускане.","Поправяй с доказателство и timecode, когато можеш.","Резултат под 80% води до повторение на посочените теми."],"nextStep":"Прегледай работата си и премини към изпита като един цял опит."},"points":1,"required":true},{"position":6,"block_key":"exam","block_type":"course_exam","title":"Предай целия изпит","content":{"introduction":"Избери най-защитимото действие при дадените условия.","questions":[{"id":"q01","moduleId":"s02-m13","prompt":"Клиентът иска четири версии, а офертата покрива една. Какво правиш?","options":[{"id":"a","label":"Уточняваш обхват, срок и цена преди обещание за останалите."},{"id":"b","label":"Обещаваш всичко и решаваш после."},{"id":"c","label":"Премахваш проверките, за да се вместиш."}]},{"id":"q02","moduleId":"s02-m13","prompt":"По време на интервю един човек трябва да снима и да следи шумния звук. Кой риск назоваваш?","options":[{"id":"a","label":"Скъпата камера автоматично решава проблема."},{"id":"b","label":"Няма риск, ако има изкуствен интелект."},{"id":"c","label":"Едновременни роли; променяш обхвата или осигуряваш втори човек."}]},{"id":"q03","moduleId":"s02-m13","prompt":"Клиентът не е потвърдил право за избраната песен. Кое е правилното предаване?","options":[{"id":"a","label":"Пишеш името на песента като достатъчен лиценз."},{"id":"b","label":"Използваш разрешена алтернатива или спираш версията до потвърждение."},{"id":"c","label":"Изпращаш финалния клип и чакаш оплакване."}]},{"id":"q04","moduleId":"s02-m13","prompt":"Как доказваш, че бюджетът е изпълним?","options":[{"id":"a","label":"Разбиваш часове, роли, разходи, ревизии и резерв за конкретния обхват."},{"id":"b","label":"Ползваш една цена за всички проекти."},{"id":"c","label":"Изчисляваш само камерата."}]},{"id":"q05","moduleId":"s02-m13","prompt":"Клиентът казва, че всички поправки са включени, но няма ограничение в брифа. Какъв е ходът?","options":[{"id":"a","label":"Остави го неясно до първия спор."},{"id":"b","label":"Откажи всяка поправка независимо от договора."},{"id":"c","label":"Уточни етапи, брой и вид ревизии и начин за приемане писмено."}]},{"id":"q06","moduleId":"s02-m13","prompt":"Имаш клиентски кадри, но няма право за твое публично портфолио. Какво можеш да покажеш?","options":[{"id":"a","label":"Клип с малко лого на клиента в ъгъла."},{"id":"b","label":"Само изрично позволен материал или анонимизиран собствен процес."},{"id":"c","label":"Целия клип, защото си го снимал."}]},{"id":"q07","moduleId":"s02-m14","prompt":"Искаш да използваш работещ чужд хук. Как адаптираш?","options":[{"id":"a","label":"Вземаш принципа, но пишеш собствено обещание и собствено доказателство."},{"id":"b","label":"Копираш текста дословно."},{"id":"c","label":"Слагаш същите кадри с друг цвят."}]},{"id":"q08","moduleId":"s02-m14","prompt":"Кое доказателство прави одита полезен?","options":[{"id":"a","label":"Оценка 6/10 без причина."},{"id":"b","label":"Списък с любими ефекти."},{"id":"c","label":"Timecode, наблюдение, приоритет и проверима поправка."}]},{"id":"q09","moduleId":"s02-m14","prompt":"На 00:18 CTA е невярно. Как подреждаш работата?","options":[{"id":"a","label":"Докладваш видеото като готово."},{"id":"b","label":"Поправяш факта преди да сменяш стилистични детайли."},{"id":"c","label":"Слагаш по-ярък преход върху CTA."}]},{"id":"q10","moduleId":"s02-m14","prompt":"Шаблонът е попълнен, но не пасва на брифа. Какво значи това?","options":[{"id":"a","label":"Структурата е подсказка; пренаписваш решението според проекта."},{"id":"b","label":"Шаблонът е по-важен от аудиторията."},{"id":"c","label":"Добавяш още три шаблона."}]},{"id":"q11","moduleId":"s02-m14","prompt":"Одитът вижда спад, но нямаш достъп до източниците на трафик. Какво твърдиш?","options":[{"id":"a","label":"Причината със сигурност е монтажът."},{"id":"b","label":"Видеото е провал, независимо от целта."},{"id":"c","label":"Това е наблюдение и хипотеза, не доказана причина."}]},{"id":"q12","moduleId":"s02-m14","prompt":"Кое предаване позволява на колега да продължи?","options":[{"id":"a","label":"Само готова миниатюра."},{"id":"b","label":"Бриф, версия, файлове, права, timecode на проблемите и следваща проверка."},{"id":"c","label":"Линк с „final“ без контекст."}]}],"minimumPercent":80},"points":36,"required":true,"answer_key":{"answers":{"q01":"a","q02":"c","q03":"b","q04":"a","q05":"c","q06":"b","q07":"a","q08":"c","q09":"b","q10":"a","q11":"c","q12":"b"}},"feedback":{"explanation":"Виж темите за повторение по-долу. Провери логиката спрямо собствения си проект."},"scoring":{"mode":"aggregate","minimumPercent":80}}]},{"module_id":"s02-m15","lesson_id":"pv15-13","title":"Общ практически изпит по FRAME","subtitle":"Общ практически изпит по решения, а не тест по определения","objective":"Решаваш обвързани задачи от целия курс с поне 80% в един опит.","hook":"Финален работен казус: малка работилница за ремонт на обувки иска един клип за хора наблизо. Собственикът има два часа за снимане; няма право да показва клиенти. Стар клип има гледания, но не знае дали води до запитвания. Записът в работилницата е шумен, а часът за приемане на обувки се мени. Имаш телефон, един микрофон и право да снимаш собственика и процеса. Избери решения, които биха оцелели при реално предаване. Отделяй потвърден факт, допускане и наблюдение.","estimated_minutes":60,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво доказваш","content":{"body":"Прилагаш работни решения от целия курс. Минимум 80% верни решения в общ опит. При непреминат изпит виждаш темите за повторение, без готов ключ."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Казусът","content":{"body":"Финален работен казус: малка работилница за ремонт на обувки иска един клип за хора наблизо. Собственикът има два часа за снимане; няма право да показва клиенти. Стар клип има гледания, но не знае дали води до запитвания. Записът в работилницата е шумен, а часът за приемане на обувки се мени. Имаш телефон, един микрофон и право да снимаш собственика и процеса. Избери решения, които биха оцелели при реално предаване. Отделяй потвърден факт, допускане и наблюдение."},"points":1,"required":true},{"position":2,"block_key":"read_case","block_type":"case_study","title":"Прочети условията, преди да отговаряш","content":{"body":"Финален работен казус: малка работилница за ремонт на обувки иска един клип за хора наблизо. Собственикът има два часа за снимане; няма право да показва клиенти. Стар клип има гледания, но не знае дали води до запитвания. Записът в работилницата е шумен, а часът за приемане на обувки се мени. Имаш телефон, един микрофон и право да снимаш собственика и процеса. Избери решения, които биха оцелели при реално предаване. Отделяй потвърден факт, допускане и наблюдение.\n\nНе добавяй права, резултати или ресурси, които брифът не дава."},"points":1,"required":true},{"position":3,"block_key":"prepare","block_type":"rich_text","title":"Провери своя проект преди изпита","content":{"body":"Отвори собствения си финален проект: бриф, план за кадри, сурови файлове, v1, тест, v2, права и проверен експорт. Изпитът изисква преминатите четири групови проверки и всички предходни уроци в модул 15. Резултатът от теста проверява професионални решения; сам по себе си не удостоверява качество или авторство на видеото."},"points":2,"required":true},{"position":4,"block_key":"rules","block_type":"rich_text","title":"Как се оценява","content":{"body":"Отговори на всички въпроси и предай целия изпит наведнъж. Сървърът оценява общия опит; успехът е от 80% нагоре. Ако не достигнеш прага, ще видиш кои модули да повториш. Грешните въпроси не показват верния избор. След повторение можеш да предадеш нов пълен опит. Това е изпит на решения; качеството и авторството на твоя видеопроект не се оценяват само от теста."},"points":1,"required":true},{"position":5,"block_key":"summary","block_type":"summary","title":"Какво да направиш след резултата","content":{"takeaways":["Отделяй факт от допускане.","Поправяй с доказателство и timecode, когато можеш.","Резултат под 80% води до повторение на посочените теми."],"nextStep":"Прегледай работата си и премини към изпита като един цял опит."},"points":1,"required":true},{"position":6,"block_key":"exam","block_type":"course_exam","title":"Предай целия изпит","content":{"introduction":"Избери най-защитимото действие при дадените условия.","questions":[{"id":"q01","moduleId":"s02-m01","prompt":"Собственикът иска повече клиенти. Коя е първата проверима цел на видеото?","options":[{"id":"a","label":"Да получи конкретен брой гледания без връзка със запитвания."},{"id":"b","label":"Да има повече ефекти от конкурентите."},{"id":"c","label":"Местният зрител да разбере услугата и как да запита, с проследим път до запитване."}]},{"id":"q02","moduleId":"s02-m01","prompt":"Стар клип има гледания, но източникът на трафик е неизвестен. Как го използваш?","options":[{"id":"a","label":"Като гаранция, че същият формат ще работи пак."},{"id":"b","label":"Като отправна точка с липсващ контекст, който първо проверяваш."},{"id":"c","label":"Като доказателство за продажби."}]},{"id":"q03","moduleId":"s02-m02","prompt":"Кой хук отговаря на брифа без неподкрепено обещание?","options":[{"id":"a","label":"Покажи конкретен дефект и първата стъпка от действителния ремонт."},{"id":"b","label":"„Всяка обувка става нова за пет минути“ без проверка."},{"id":"c","label":"Лого и слоган без контекст за зрителя."}]},{"id":"q04","moduleId":"s02-m02","prompt":"Клипът завършва с „Пиши ни“, но профилът няма работещ бутон. Какво поправяш?","options":[{"id":"a","label":"Оставяш CTA, защото звучи естествено."},{"id":"b","label":"Добавяш повече хаштагове вместо канал."},{"id":"c","label":"Потвърждаваш реален канал и показваш точното следващо действие."}]},{"id":"q05","moduleId":"s02-m03","prompt":"Детайл на шев се губи, защото телефонът фокусира фона. Какво правиш на място?","options":[{"id":"a","label":"Увеличи FPS без смяна на фокус."},{"id":"b","label":"Настрой фокус за важния детайл и прегледай реалния дубъл."},{"id":"c","label":"Разчитай на увеличение в монтажа на размазан файл."}]},{"id":"q06","moduleId":"s02-m03","prompt":"Снимаш движение на ръце от два ъгъла. Как пазиш разбираемостта?","options":[{"id":"a","label":"Съгласуваш посока и действие, снимаш покритие за смислен разрез."},{"id":"b","label":"Разчиташ на бързи преходи да прикрият всяка грешка."},{"id":"c","label":"Сменяш посоката на действието между дублите без причина."}]},{"id":"q07","moduleId":"s02-m04","prompt":"Прозорецът прави кожата твърде тъмна, а фонът е светъл. Какъв е първият ход?","options":[{"id":"a","label":"Изчакай цветната обработка да върне липсващи детайли."},{"id":"b","label":"Постави случайна лампа с различен цвят без проба."},{"id":"c","label":"Промени позицията и експозицията според важния субект, после тествай."}]},{"id":"q08","moduleId":"s02-m04","prompt":"Кадрите от сутрин и вечер имат различен цветен баланс. Как действаш?","options":[{"id":"a","label":"Оставяш разликата, защото е художествена по подразбиране."},{"id":"b","label":"Изравняваш експозиция и баланс за последователност преди творчески стил."},{"id":"c","label":"Слагаш различен LUT на всяка сцена."}]},{"id":"q09","moduleId":"s02-m05","prompt":"На пробата пресата заглушава най-важната реплика. Кой ход е надежден?","options":[{"id":"a","label":"Запиши репликата на тихо и провери със слушалки, а процеса заснеми отделно."},{"id":"b","label":"Повтори по-силно върху работещата преса без прослушване."},{"id":"c","label":"Остави AI да измисли липсващите думи."}]},{"id":"q10","moduleId":"s02-m05","prompt":"Музиката в експорта покрива кратко обяснение. Как го поправяш?","options":[{"id":"a","label":"Покачване на общата сила на звука до максимум."},{"id":"b","label":"Изтриване на цялото видео без проверка."},{"id":"c","label":"Баланс на нива и ново прослушване на реалния експорт."}]},{"id":"q11","moduleId":"s02-m06","prompt":"Собственикът може да участва само в началото. Кой снимачен ред избираш?","options":[{"id":"a","label":"Всичко в произволен ред без план."},{"id":"b","label":"Първо критичните му реплики и действия; B-roll след това."},{"id":"c","label":"Първо празни кадри на фасадата, докато му свърши времето."}]},{"id":"q12","moduleId":"s02-m06","prompt":"Клиент без разрешение влиза в кадър. Как продължаваш?","options":[{"id":"a","label":"Спри този дубъл и пренареди сцената към позволени хора и кадри."},{"id":"b","label":"Публикувай и поискайте разрешение после."},{"id":"c","label":"Остави кадъра, ако човекът е на заден план."}]},{"id":"q13","moduleId":"s02-m07","prompt":"Имаш бюджет само за една добавка към телефона. Кой проблем оправяш първо?","options":[{"id":"a","label":"Най-ефектната джаджа независимо от теста."},{"id":"b","label":"По-скъп калъф вместо пробен запис."},{"id":"c","label":"Реалния блокиращ проблем, например неразбираем говор с подходящ микрофон."}]},{"id":"q14","moduleId":"s02-m07","prompt":"Клипът изглежда измит след прехвърляне от телефона. Кое проверяваш?","options":[{"id":"a","label":"Дали платформата има повече последователи."},{"id":"b","label":"HDR/SDR и цветния работен поток на целевия експорт и устройство."},{"id":"c","label":"Само името на файла."}]},{"id":"q15","moduleId":"s02-m08","prompt":"Снимаш серия за четири услуги. Как организираш деня?","options":[{"id":"a","label":"Групираш сцените по настройка и пазиш отделен контрол за всяко послание."},{"id":"b","label":"Рестартираш осветлението след всеки отделен кадър."},{"id":"c","label":"Снимаш без подредени сценарии, за да е спонтанно."}]},{"id":"q16","moduleId":"s02-m08","prompt":"След снимките телефонът е единственото място с материала. Какво правиш?","options":[{"id":"a","label":"Изтриваш ненужните на око още на терен."},{"id":"b","label":"Пращаш един компресиран клип в чат и приключваш."},{"id":"c","label":"Създаваш и проверяваш независими копия с ясни папки преди да изтриеш оригинали."}]},{"id":"q17","moduleId":"s02-m09","prompt":"На таймлайна поправката на обувка изглежда ясна, но след експорт надписът е отрязан. Какво следва?","options":[{"id":"a","label":"Остави зрителя да обърне телефона."},{"id":"b","label":"Коригирай безопасната зона и прегледай новия експорт на целевия телефон."},{"id":"c","label":"Публикувай, защото таймлайнът е верен."}]},{"id":"q18","moduleId":"s02-m09","prompt":"Монтажът пропуска стъпка и резултатът изглежда като магия. Коя е редакционната поправка?","options":[{"id":"a","label":"Покажи ключовото действие или назови честно пропуснатия процес."},{"id":"b","label":"Ускори още повече, за да не се забележи."},{"id":"c","label":"Добави произволен стоков кадър като доказателство."}]},{"id":"q19","moduleId":"s02-m10","prompt":"Подготвени са хоризонтална и вертикална версия. Коя проверка е задължителна за двете?","options":[{"id":"a","label":"Само дали имат различни имена."},{"id":"b","label":"Само дали вертикалната е по-къса."},{"id":"c","label":"Отделно кадриране, четимост, надписи, звук и работещо действие."}]},{"id":"q20","moduleId":"s02-m10","prompt":"Миниатюрата показва невъзможен „преди/след“ резултат. Какво публикуваш?","options":[{"id":"a","label":"Още по-силно редактиран резултат."},{"id":"b","label":"Реален кадър и обещание, които съдържанието доказва."},{"id":"c","label":"Подвеждащата миниатюра, ако има повече кликове."}]},{"id":"q21","moduleId":"s02-m11","prompt":"Задържането пада на 00:14, когато започва обяснение. Как проверяваш причината?","options":[{"id":"a","label":"Гледаш точното място, източника на трафик и обещаното преди него; формулираш хипотеза."},{"id":"b","label":"Приемаш, че всяко обяснение е грешка."},{"id":"c","label":"Изрязваш 00:14 без преглед на смисъла."}]},{"id":"q22","moduleId":"s02-m11","prompt":"Нямаш отчет за задържане два часа след публикация. Какво записваш?","options":[{"id":"a","label":"Нула процента задържане."},{"id":"b","label":"Приблизителна крива, наречена реална."},{"id":"c","label":"Че отчетът липсва, и кога ще го провериш; използваш налични наблюдения отделно."}]},{"id":"q23","moduleId":"s02-m12","prompt":"AI предложи „ремонтът удължава живота с десет години“. Няма източник. Какво правиш?","options":[{"id":"a","label":"Слагаш го в надпис без глас, за да не носиш отговорност."},{"id":"b","label":"Изваждаш твърдението или проверяваш надежден източник и приложимост."},{"id":"c","label":"Оставяш го, защото звучи убедително."}]},{"id":"q24","moduleId":"s02-m12","prompt":"AI почиства запис и променя думата „понякога“ на „винаги“. Кой файл предаваш?","options":[{"id":"a","label":"Поправения спрямо оригинала и проверен финален експорт."},{"id":"b","label":"По-чистия, въпреки невярното твърдение."},{"id":"c","label":"И двата без да посочиш кое е вярно."}]},{"id":"q25","moduleId":"s02-m13","prompt":"Клиентът добавя още две версии след фиксираната цена. Как реагираш?","options":[{"id":"a","label":"Правиш ги без уточнение и губиш време за проверка."},{"id":"b","label":"Премахваш лицензите, за да спестиш разход."},{"id":"c","label":"Посочваш нов обхват, часове, ревизии, срок и писмено одобрение."}]},{"id":"q26","moduleId":"s02-m13","prompt":"За музиката има линк за слушане, но няма право за търговска употреба. Какъв е ходът?","options":[{"id":"a","label":"Слагаш кредит и приемаш, че е достатъчен."},{"id":"b","label":"Проверяваш лиценза или сменяш с разрешен актив преди публикуване."},{"id":"c","label":"Оставяш, ако авторът не отговори."}]},{"id":"q27","moduleId":"s02-m14","prompt":"Чужд клип има силен монтажен ритъм. Как го използваш почтено?","options":[{"id":"a","label":"Извличаш принцип и го проверяваш със собствен кадър, тема и аудитория."},{"id":"b","label":"Копираш кадрите и текста за същия ефект."},{"id":"c","label":"Само сменяш шрифта на чуждия сценарий."}]},{"id":"q28","moduleId":"s02-m14","prompt":"Одитът намира грешен час на приемане на 00:38 и бавен преход на 00:07. Кое решаваш първо?","options":[{"id":"a","label":"Първо сменяш прехода, защото е видим."},{"id":"b","label":"Пускаш видеото и събираш реакция за часа."},{"id":"c","label":"Потвърждаваш часа и поправяш неверния факт преди стилистичния преход."}]},{"id":"q29","moduleId":"s02-m15","prompt":"Частният тест показва, че двама души не разбират как да запитат. Коя е v2?","options":[{"id":"a","label":"Обявяване на успех без нова проверка."},{"id":"b","label":"Поправка на конкретния CTA с потвърден канал и повторен тест на същия въпрос."},{"id":"c","label":"Промяна на всички кадри без проследяване."}]},{"id":"q30","moduleId":"s02-m15","prompt":"Кой финален отчет можеш честно да предадеш?","options":[{"id":"a","label":"Бриф, версия, права, наблюдение, поправка, резултат и ясно неизвестно."},{"id":"b","label":"„Удвоихме продажбите“ въз основа на мнения на трима зрители."},{"id":"c","label":"Един final.mp4 без процес, права и контекст."}]}],"minimumPercent":80},"points":60,"required":true,"answer_key":{"answers":{"q01":"c","q02":"b","q03":"a","q04":"c","q05":"b","q06":"a","q07":"c","q08":"b","q09":"a","q10":"c","q11":"b","q12":"a","q13":"c","q14":"b","q15":"a","q16":"c","q17":"b","q18":"a","q19":"c","q20":"b","q21":"a","q22":"c","q23":"b","q24":"a","q25":"c","q26":"b","q27":"a","q28":"c","q29":"b","q30":"a"}},"feedback":{"explanation":"Виж темите за повторение по-долу. Провери логиката спрямо собствения си проект."},"scoring":{"mode":"aggregate","minimumPercent":80}}]}]$curriculum$::jsonb;
  lesson record;
  item jsonb;
  lesson_uuid uuid;
  version_uuid uuid;
  block_uuid uuid;
  report jsonb;
  total integer;
  keys integer;
BEGIN
  IF jsonb_typeof(payload)<>'array' OR jsonb_array_length(payload)<>13 OR
     (SELECT array_agg(p.lesson_id ORDER BY p.lesson_id)
      FROM jsonb_to_recordset(payload) p(lesson_id text))<>ARRAY['pv15-01','pv15-02','pv15-03','pv15-04','pv15-05','pv15-06','pv15-07','pv15-08','pv15-09','pv15-10','pv15-11','pv15-12','pv15-13']::text[] OR
     (SELECT count(DISTINCT p.lesson_id) FROM jsonb_to_recordset(payload) p(lesson_id text))<>13 THEN
    RAISE EXCEPTION 'Unexpected module 15 lesson IDs';
  END IF;
  IF EXISTS (SELECT 1 FROM public.academy_lessons WHERE module_id='s02-m15') OR
     EXISTS (SELECT 1 FROM public.interactive_lessons WHERE module_id='s02-m15') THEN
    RAISE EXCEPTION 'Module 15 already exists; review before publishing';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(payload) p(
      module_id text,lesson_id text,title text,objective text,hook text,
      estimated_minutes integer,blocks jsonb)
    WHERE p.module_id<>'s02-m15' OR btrim(p.title)='' OR btrim(p.objective)=''
       OR btrim(p.hook)='' OR p.estimated_minutes NOT BETWEEN 25 AND 60
       OR jsonb_typeof(p.blocks)<>'array'
       OR jsonb_array_length(p.blocks) NOT BETWEEN 7 AND 20
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='course_exam')<>(CASE WHEN p.lesson_id>='pv15-09' THEN 1 ELSE 0 END)
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type' IN ('homework','reflection','practical_response'))
  ) THEN RAISE EXCEPTION 'Module 15 content guard failed'; END IF;

  FOR lesson IN SELECT * FROM jsonb_to_recordset(payload) p(
    module_id text,lesson_id text,title text,subtitle text,objective text,
    hook text,estimated_minutes integer,blocks jsonb) ORDER BY lesson_id LOOP
    INSERT INTO public.academy_lessons(module_id,lesson_id,status)
    VALUES(lesson.module_id,lesson.lesson_id,'draft') RETURNING id INTO lesson_uuid;
    INSERT INTO public.academy_lesson_versions(
      academy_lesson_id,version_number,title,subtitle,duration,objective,hook,
      estimated_minutes,source_kind,change_note)
    VALUES(lesson_uuid,1,lesson.title,lesson.subtitle,
      lesson.estimated_minutes::text||' минути',lesson.objective,lesson.hook,
      lesson.estimated_minutes,'editor','FRAME финален проект и практични изпити v9')
    RETURNING id INTO version_uuid;
    FOR item IN SELECT value FROM jsonb_array_elements(lesson.blocks) LOOP
      INSERT INTO public.academy_lesson_blocks(
        version_id,block_key,"position",block_type,title,content,required,points)
      VALUES(version_uuid,item->>'block_key',(item->>'position')::integer,
        item->>'block_type',item->>'title',item->'content',
        (item->>'required')::boolean,(item->>'points')::integer)
      RETURNING id INTO block_uuid;
      IF item ? 'answer_key' THEN
        INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring)
        VALUES(block_uuid,item->'answer_key',item->'feedback',item->'scoring');
      END IF;
    END LOOP;
    report:=academy_private.lesson_validation(version_uuid);
    IF jsonb_array_length(report->'errors')<>0 OR jsonb_array_length(report->'warnings')<>0 THEN
      RAISE EXCEPTION 'Lesson % failed validation: %',lesson.lesson_id,report;
    END IF;
    UPDATE public.academy_lesson_versions SET validation=report WHERE id=version_uuid;
    UPDATE public.academy_lessons SET status='published',published_version_id=version_uuid,
      draft_version_id=version_uuid,updated_at=clock_timestamp() WHERE id=lesson_uuid;
    INSERT INTO public.academy_lesson_audit(
      academy_lesson_id,version_id,actor_id,action,details)
    VALUES(lesson_uuid,version_uuid,NULL,'published',
      jsonb_build_object('source','perfect_video_v9','preserved_existing_progress',true));
  END LOOP;
  SELECT count(*) INTO total FROM public.academy_lessons
    WHERE module_id='s02-m15' AND status='published' AND published_version_id IS NOT NULL;
  SELECT count(*) INTO keys FROM academy_private.lesson_block_keys k
    JOIN public.academy_lesson_blocks b ON b.id=k.block_id
    JOIN public.academy_lesson_versions v ON v.id=b.version_id
    JOIN public.academy_lessons l ON l.id=v.academy_lesson_id
    WHERE l.module_id='s02-m15' AND l.published_version_id=v.id;
  IF total<>13 OR keys<>45 THEN RAISE EXCEPTION 'Release incomplete: % lessons, % keys',total,keys; END IF;
END $release$;
